import base64
import hashlib
import os


def task_func(password, SALT_LENGTH=32):
    if password is None or password == "" or password == b"":
        raise ValueError("Password cannot be None or empty")

    if isinstance(password, str):
        password = password.encode("utf-8")
    elif not isinstance(password, bytes):
        raise TypeError("Password must be a string or bytes")

    if SALT_LENGTH <= 0:
        raise ValueError("SALT_LENGTH must be positive")

    salt = os.urandom(SALT_LENGTH)
    hashed_password = hashlib.pbkdf2_hmac(
        "sha256",
        password,
        salt,
        100_000,
        dklen=32,
    )

    return base64.b64encode(salt), base64.b64encode(hashed_password)

import re
import os
from urllib.parse import unquote


def task_func(request):
    def response(status, body=""):
        return f"HTTP/1.1 {status}\r\n\r\n{body}"

    if not isinstance(request, str) or not request.strip():
        return response("400 Bad Request", "Bad Request")

    request_line = request.splitlines()[0].strip()
    match = re.fullmatch(
        r"GET\s+(\S+)(?:\s+HTTP/\d+(?:\.\d+)?)?",
        request_line,
    )

    if not match:
        return response("400 Bad Request", "Bad Request")

    target = match.group(1).split("?", 1)[0]

    try:
        target = unquote(target)
    except Exception:
        return response("400 Bad Request", "Bad Request")

    if not target or "\x00" in target:
        return response("400 Bad Request", "Bad Request")

    target = target.replace("\\", "/")

    if re.match(r"^[A-Za-z]:", target) or target.startswith("//"):
        return response("400 Bad Request", "Bad Request")

    parts = target.split("/")
    if any(part == ".." for part in parts):
        return response("400 Bad Request", "Bad Request")

    relative_path = target.lstrip("/")
    if not relative_path:
        return response("404 Not Found", "File Not Found")

    try:
        base_dir = os.path.realpath(os.getcwd())
        file_path = os.path.realpath(os.path.join(base_dir, relative_path))

        if os.path.commonpath((base_dir, file_path)) != base_dir:
            return response("400 Bad Request", "Bad Request")

        if not os.path.isfile(file_path):
            return response("404 Not Found", "File Not Found")

        with open(file_path, "rb") as file:
            content = file.read()
    except (OSError, ValueError, UnicodeError):
        return response("404 Not Found", "File Not Found")

    try:
        body = content.decode("utf-8")
    except UnicodeDecodeError:
        body = content.decode("latin-1")

    return (
        "HTTP/1.1 200 OK\r\n"
        f"Content-Length: {len(content)}\r\n"
        "\r\n"
        f"{body}"
    )

import numpy as np
from scipy import stats


def task_func(df, column, alpha):
    if column not in df.columns:
        raise KeyError(column)

    try:
        alpha = float(alpha)
    except (TypeError, ValueError, OverflowError) as exc:
        raise ValueError("alpha must be a finite number") from exc

    if not np.isfinite(alpha) or not 0 < alpha < 1:
        raise ValueError("alpha must be between 0 and 1")

    try:
        values = np.asarray(df[column], dtype=float)
    except (TypeError, ValueError) as exc:
        raise ValueError("The selected column must contain numeric values") from exc

    values = values[np.isfinite(values)]

    if values.size < 3:
        raise ValueError("At least 3 valid observations are required")

    if np.all(values == values[0]):
        return False

    _, p_value = stats.shapiro(values)
    return bool(p_value > alpha)

import pandas as pd
from sklearn.ensemble import RandomForestClassifier
import seaborn as sns
import matplotlib.pyplot as plt


def task_func(df, target_column):
    if df.columns.duplicated().any():
        raise ValueError("The dataframe must not contain duplicate column names.")

    if target_column not in df.columns:
        raise KeyError(f"Target column '{target_column}' not found.")

    if df.empty:
        raise ValueError("The dataframe must not be empty.")

    feature_columns = [column for column in df.columns if column != target_column]
    if not feature_columns:
        raise ValueError("The dataframe must contain at least one feature column.")

    if df[target_column].isna().any():
        raise ValueError("The target column must not contain missing values.")

    if df[target_column].nunique() < 2:
        raise ValueError("The target column must contain at least two classes.")

    X = df[feature_columns]
    y = df[target_column]

    if not all(pd.api.types.is_numeric_dtype(X[column]) for column in feature_columns):
        raise ValueError("All feature columns must be numeric.")

    if X.isna().any().any():
        raise ValueError("Feature columns must not contain missing values.")

    classifier = RandomForestClassifier(random_state=42)
    classifier.fit(X, y)

    importance_df = pd.DataFrame(
        {
            "Feature": feature_columns,
            "Importance": classifier.feature_importances_,
        }
    ).sort_values("Importance", ascending=False)

    _, ax = plt.subplots()
    sns.barplot(
        data=importance_df,
        x="Importance",
        y="Feature",
        ax=ax,
    )

    ax.set_xlabel("Feature Importance Score")
    ax.set_ylabel("Features")
    ax.set_title("Visualizing Important Features")

    return classifier, ax

