import urllib.request
import os
import csv
import collections


def task_func(url, column_name, csv_file_path):
    downloaded = False

    try:
        urllib.request.urlretrieve(url, csv_file_path)
        downloaded = True

        with open(csv_file_path, "r", encoding="utf-8", newline="") as csv_file:
            reader = csv.DictReader(csv_file)

            if not reader.fieldnames or column_name not in reader.fieldnames:
                raise ValueError(
                    f"The provided column_name '{column_name}' does not exist in the CSV file."
                )

            counts = collections.Counter(row[column_name] for row in reader)
            return dict(counts)
    finally:
        if downloaded and os.path.exists(csv_file_path):
            try:
                os.remove(csv_file_path)
            except OSError:
                pass

import pandas as pd
import seaborn as sns
import numpy as np
import ast


def task_func(csv_file):
    columns = ["email", "list", "sum", "mean", "std"]

    try:
        data = pd.read_csv(csv_file)
    except pd.errors.EmptyDataError:
        return pd.DataFrame(columns=columns), sns.histplot(x=[])

    if not {"email", "list"}.issubset(data.columns):
        raise ValueError("CSV file must contain 'email' and 'list' columns.")

    parsed_lists = []

    for value in data["list"]:
        if value is None or (isinstance(value, float) and np.isnan(value)):
            raise ValueError("Missing value in 'list' column.")

        try:
            values = ast.literal_eval(value)
        except (ValueError, SyntaxError, TypeError) as exc:
            raise ValueError(f"Invalid list value: {value!r}") from exc

        if not isinstance(values, list):
            raise ValueError(f"Expected a list, got: {values!r}")

        if any(
            isinstance(item, bool) or not isinstance(item, (int, float))
            for item in values
        ):
            raise ValueError(f"List contains non-numeric values: {values!r}")

        parsed_lists.append(values)

    result = pd.DataFrame(
        {
            "email": data["email"],
            "list": parsed_lists,
            "sum": [sum(values) for values in parsed_lists],
            "mean": [
                np.mean(values) if values else np.nan
                for values in parsed_lists
            ],
            "std": [
                np.std(values, ddof=0) if values else np.nan
                for values in parsed_lists
            ],
        },
        columns=columns,
    )

    axes = sns.histplot(data=result, x="mean")
    return result, axes

