import pandas as pd
import numpy as np
import itertools
from datetime import datetime, timedelta
import seaborn as sns


def task_func(df, fruits=None, days=None, seed=None, sales_lower_bound=1, sales_upper_bound=50):
    if not isinstance(df, pd.DataFrame):
        raise TypeError("'df' must be a pandas DataFrame")

    if not df.empty:
        raise ValueError("'df' must be empty")

    if sales_lower_bound >= sales_upper_bound:
        raise ValueError(
            "'sales_lower_bound' must be less than 'sales_upper_bound'"
        )

    if fruits is None:
        fruits = ["Apple", "Banana", "Orange"]
    elif isinstance(fruits, str):
        fruits = [fruits]
    else:
        fruits = list(fruits)

    if days is None:
        start_date = datetime(2020, 1, 1)
        days = [start_date + timedelta(days=i) for i in range(7)]
    elif isinstance(days, (int, np.integer)):
        if days < 0:
            raise ValueError("'days' must not be negative")
        start_date = datetime(2020, 1, 1)
        days = [start_date + timedelta(days=i) for i in range(days)]
    elif isinstance(days, (str, datetime)):
        days = [days]
    else:
        days = list(days)

    combinations = list(itertools.product(fruits, days))
    rng = np.random.default_rng(seed)

    generated = pd.DataFrame(combinations, columns=["fruit", "day"])
    generated["sales"] = rng.integers(
        sales_lower_bound,
        sales_upper_bound,
        size=len(generated),
    )

    updated_df = pd.concat([df, generated], ignore_index=True)

    plot = sns.catplot(
        data=updated_df,
        x="fruit",
        y="sales",
        kind="box",
    )

    return updated_df, plot

