import pandas as pd
import numpy as np
import numbers


def task_func(start_time, end_time, step, trend, seed=42):
    import matplotlib.pyplot as plt

    try:
        start = pd.Timestamp(start_time)
        end = pd.Timestamp(end_time)
        if pd.isna(start) or pd.isna(end):
            raise ValueError
    except Exception as exc:
        raise ValueError(
            "start_time and end_time must be valid datetimes"
        ) from exc

    if start > end:
        raise ValueError("start_time must not be later than end_time")

    if isinstance(step, (int, float, np.number)) and not isinstance(step, bool):
        raise ValueError("step must be a positive pandas-compatible frequency")

    try:
        offset = pd.tseries.frequencies.to_offset(step)
        if offset.n <= 0:
            raise ValueError
        timestamps = pd.date_range(start=start, end=end, freq=offset)
    except Exception as exc:
        raise ValueError(
            "step must be a valid positive pandas frequency"
        ) from exc

    if len(timestamps) == 0:
        raise ValueError("The generated timestamp range is empty")

    if not isinstance(trend, numbers.Real) or isinstance(trend, bool):
        raise TypeError("trend must be numeric")

    if seed is not None and (
        not isinstance(seed, numbers.Integral) or isinstance(seed, bool)
    ):
        raise TypeError("seed must be an integer or None")

    rng = np.random.default_rng(seed)
    values = rng.normal(size=len(timestamps))
    values += float(trend) * np.arange(len(timestamps))

    _, ax = plt.subplots()
    ax.plot(timestamps, values)
    ax.set_xlabel("Time")
    ax.set_ylabel("Value")

    return ax

