import pandas as pd
import matplotlib.pyplot as plt


def task_func(file_path):
    """Identify duplicate rows in a CSV file and plot their counts."""
    if not isinstance(file_path, (str, bytes)):
        try:
            file_path = file_path.__fspath__()
        except AttributeError as exc:
            raise ValueError("file_path must be a CSV file path") from exc

    extension_path = (
        file_path.decode(errors="ignore") if isinstance(file_path, bytes) else file_path
    )
    if not extension_path.lower().endswith(".csv"):
        raise ValueError("file_path must have a .csv extension")

    try:
        with open(file_path, "r", encoding="utf-8", newline="") as csv_file:
            rows = [tuple(row) for row in csv.reader(csv_file, strict=True)]
    except csv.Error as exc:
        raise ValueError("The CSV file is not properly formatted") from exc

    counts = Counter(rows)
    duplicate_counts = {
        row: count for row, count in counts.items() if count > 1
    }

    duplicate_df = pd.DataFrame(
        {
            "row": [repr(row) for row in duplicate_counts],
            "count": list(duplicate_counts.values()),
        }
    )

    _, ax = plt.subplots()
    if not duplicate_df.empty:
        ax.bar(duplicate_df["row"], duplicate_df["count"])
        ax.tick_params(axis="x", labelrotation=45)
        for label in ax.get_xticklabels():
            label.set_ha("right")

    ax.set_xlabel("Duplicate row")
    ax.set_ylabel("Count")
    ax.set_title("Duplicate CSV Rows")
    return duplicate_counts, ax

import re
import json
import requests

API_ENDPOINT = "https://example.com/api"


def task_func(myString, token):
    if not isinstance(myString, str) or not myString.strip():
        raise ValueError("myString must be a non-empty string")

    if not isinstance(token, str) or not token.strip():
        raise ValueError("token must be a non-empty string")

    match = re.search(r"https?://[^\s<>'\"]+", myString)
    if match is None:
        raise ValueError("No URL found in myString")

    url = match.group(0).rstrip(".,;:!?)]}")
    if not url:
        raise ValueError("Extracted URL is empty")

    response = requests.post(
        API_ENDPOINT,
        json={"url": url},
        headers={
            "Authorization": f"Bearer {token}",
            "Content-Type": "application/json",
        },
        timeout=30,
    )
    response.raise_for_status()

    try:
        result = response.json()
    except (ValueError, json.JSONDecodeError) as exc:
        raise ValueError("API response is not valid JSON") from exc

    if not isinstance(result, dict):
        raise TypeError("API response must be a dictionary")

    return result

