# Constants
CITIES = ['New York', 'London', 'Beijing', 'Tokyo', 'Sydney', 'Paris', 'Berlin', 'Moscow', 'Madrid', 'Rome']


def task_func(city_dict, max_range=1000000, seed=0):
    if not isinstance(city_dict, dict):
        raise TypeError("city_dict must be a dictionary")
    if not isinstance(max_range, (int, np.integer)) or isinstance(max_range, bool):
        raise TypeError("max_range must be an integer")
    if max_range <= 0:
        raise ValueError("max_range must be greater than zero")

    cities = []
    for city in city_dict.values():
        if not isinstance(city, str):
            raise TypeError("Favorite cities must be strings")
        if city not in cities:
            cities.append(city)

    np.random.seed(seed)

    population_dict = {
        city: int(np.random.randint(1, max_range + 1))
        if city in CITIES else -1
        for city in cities
    }

    _, ax = plt.subplots()
    ax.bar(list(population_dict.keys()), list(population_dict.values()))
    ax.set_xlabel("City")
    ax.set_ylabel("Population")
    ax.set_title("City Populations")
    ax.figure.tight_layout()

    return population_dict, ax

