import json
import csv
import os
import base64


def task_func(raw_string, filename, output_dir):
    if not isinstance(raw_string, str):
        raise TypeError("raw_string must be a string")

    if (
        not isinstance(filename, str)
        or not filename
        or filename in {".", ".."}
        or os.path.basename(filename) != filename
    ):
        raise ValueError("filename must be a valid name without path components")

    decoded = base64.b64decode(raw_string, validate=True)
    data = json.loads(decoded.decode("utf-8"))

    if not isinstance(data, list):
        raise TypeError("decoded JSON must be a list of dictionaries")

    if any(not isinstance(record, dict) for record in data):
        raise TypeError("each JSON record must be a dictionary")

    fieldnames = []
    for record in data:
        for key in record:
            if key not in fieldnames:
                fieldnames.append(key)

    os.makedirs(output_dir, exist_ok=True)
    file_path = os.path.join(output_dir, filename)

    def serialize_value(value):
        if isinstance(value, (dict, list)):
            return json.dumps(value, ensure_ascii=False)
        return value

    with open(file_path, "w", encoding="utf-8", newline="") as csv_file:
        if fieldnames:
            writer = csv.DictWriter(csv_file, fieldnames=fieldnames)
            writer.writeheader()
            for record in data:
                writer.writerow({
                    key: serialize_value(record.get(key, ""))
                    for key in fieldnames
                })

    return file_path

import pandas as pd
import re
import random


def task_func(s: str, seed: int = 0) -> pd.DataFrame:
    columns = ["ID", "Quantity", "Code", "Price", "Product", "Description"]
    products = ["Apple", "Banana", "Orange", "Pear", "Grape"]

    rng = random.Random(seed)
    code_to_product = {}
    rows = []

    for line_number, line in enumerate(s.splitlines(), start=1):
        line = line.strip()
        if not line:
            continue

        parts = re.split(r"\s+", line, maxsplit=4)
        if len(parts) != 5:
            raise ValueError(
                f"Line {line_number} must contain ID, quantity, code, price, "
                "and description"
            )

        id_value, quantity, code, price, description = (
            part.strip() for part in parts
        )

        try:
            id_value = int(id_value)
            quantity = int(quantity)
            price = int(price)
        except ValueError as exc:
            raise ValueError(
                f"Line {line_number} contains non-integer ID, quantity, or price"
            ) from exc

        if code not in code_to_product:
            code_to_product[code] = rng.choice(products)

        rows.append(
            {
                "ID": id_value,
                "Quantity": quantity,
                "Code": code,
                "Price": price,
                "Product": code_to_product[code],
                "Description": description,
            }
        )

    return pd.DataFrame(rows, columns=columns)

import itertools
import math
from pandas import Series

def task_func(elements, subset_size, top_n=2):
    if subset_size > len(elements) or subset_size == 0:
        return 1

    subset_sums = [
        sum(subset)
        for subset in itertools.combinations(elements, subset_size)
    ]

    product = math.prod(subset_sums)
    top_sums = Series(
        sorted(subset_sums, reverse=True)[:max(0, top_n)]
    )

    return product, top_sums

import subprocess
import os
import signal
import time


def task_func(process_name: str) -> int:
    if not isinstance(process_name, str) or not process_name.strip():
        return 0

    target_name = process_name.strip().casefold()
    current_pid = os.getpid()
    processes = []

    try:
        if os.name == "nt":
            result = subprocess.run(
                ["tasklist", "/FO", "CSV", "/NH"],
                capture_output=True,
                text=True,
                check=False,
            )
            output = result.stdout or ""
            for line in output.splitlines():
                fields = line.split('","')
                if len(fields) < 2:
                    continue

                name = fields[0].lstrip('"')
                pid_text = fields[1].strip().strip('"')

                try:
                    pid = int(pid_text)
                except ValueError:
                    continue

                processes.append((pid, name))
        else:
            result = subprocess.run(
                ["ps", "-eo", "pid=,comm="],
                capture_output=True,
                text=True,
                check=False,
            )
            output = result.stdout or ""
            for line in output.splitlines():
                parts = line.strip().split(None, 1)
                if len(parts) != 2:
                    continue

                try:
                    pid = int(parts[0])
                except ValueError:
                    continue

                processes.append((pid, parts[1]))

    except (OSError, subprocess.SubprocessError):
        return 0

    stopped = 0

    for pid, name in processes:
        if pid == current_pid or name.strip().casefold() != target_name:
            continue

        try:
            os.kill(pid, signal.SIGTERM)
            stopped += 1
        except (OSError, ValueError):
            continue

    if stopped:
        time.sleep(1)

    return stopped

