# Constants
SAMPLE_ENGLISH_WORDS = set(words.words())  # Correct initialization

ENGLISH_WORDS = {word.lower() for word in SAMPLE_ENGLISH_WORDS}


def task_func(s, n):
    if not isinstance(s, str):
        raise TypeError("s must be a string")
    if not isinstance(n, int):
        raise TypeError("n must be an integer")
    if n <= 0:
        return []

    extracted_words = re.findall(r"[A-Za-z]+", s.lower())
    distinct_words = {
        word for word in extracted_words if word in ENGLISH_WORDS
    }

    if len(distinct_words) <= n:
        return list(distinct_words)

    return sample(list(distinct_words), n)

import string
