import os
import shutil

# Constants
BACKUP_DIR = '/tmp/backup'


def get_unique_backup_dir():
    return "/fake/backup/path"


def task_func(directory):
    errors = []

    try:
        backup_path = get_unique_backup_dir()
        source = os.path.abspath(os.fspath(directory))
        candidate = os.path.abspath(os.fspath(backup_path))
    except Exception as exc:
        return BACKUP_DIR, [f"Could not determine paths: {exc}"]

    if not os.path.isdir(source):
        return backup_path, [f"Source directory does not exist: {directory}"]

    source_real = os.path.realpath(source)
    candidate_real = os.path.realpath(candidate)

    try:
        if os.path.commonpath([source_real, candidate_real]) == source_real:
            return backup_path, [
                "Backup directory cannot be the source directory or be inside it."
            ]
    except ValueError:
        pass

    parent = os.path.dirname(candidate)
    name = os.path.basename(candidate)
    index = 1

    while os.path.lexists(candidate):
        candidate = os.path.join(parent, f"{name}_{index}")
        index += 1

    backup_path = candidate

    try:
        os.makedirs(backup_path, exist_ok=False)
    except Exception as exc:
        return backup_path, [f"Could not create backup directory: {exc}"]

    def copy_entry(src, dst):
        try:
            if os.path.islink(src):
                os.symlink(os.readlink(src), dst)
                return True

            if os.path.isdir(src):
                os.makedirs(dst, exist_ok=False)
                success = True

                try:
                    names = os.listdir(src)
                except Exception as exc:
                    errors.append(f"Could not list directory {src}: {exc}")
                    return False

                for entry in names:
                    if not copy_entry(
                        os.path.join(src, entry),
                        os.path.join(dst, entry),
                    ):
                        success = False

                try:
                    shutil.copystat(src, dst, follow_symlinks=False)
                except Exception as exc:
                    errors.append(f"Could not copy metadata for {src}: {exc}")
                    success = False

                return success

            shutil.copy2(src, dst, follow_symlinks=False)
            return True

        except Exception as exc:
            errors.append(f"Could not back up {src}: {exc}")
            return False

    def remove_entry(path):
        try:
            if os.path.islink(path) or not os.path.isdir(path):
                os.remove(path)
                return True

            success = True
            for entry in os.listdir(path):
                if not remove_entry(os.path.join(path, entry)):
                    success = False

            try:
                os.rmdir(path)
            except Exception as exc:
                errors.append(f"Could not clean directory {path}: {exc}")
                success = False

            return success

        except Exception as exc:
            errors.append(f"Could not clean {path}: {exc}")
            return False

    try:
        entries = os.listdir(source)
    except Exception as exc:
        return backup_path, [f"Could not list source directory {source}: {exc}"]

    successful_entries = []

    for name in entries:
        src = os.path.join(source, name)
        dst = os.path.join(backup_path, name)

        if copy_entry(src, dst):
            successful_entries.append(src)

    for src in successful_entries:
        remove_entry(src)

    return backup_path, errors

import numpy as np
import seaborn as sns


def task_func(P, T):
    if not isinstance(P, np.ndarray) or not isinstance(T, np.ndarray):
        raise TypeError("P and T must be NumPy arrays or matrices.")

    if P.ndim != 2:
        raise ValueError("P must be a 2D matrix.")
    if T.ndim != 3:
        raise ValueError("T must be a 3D tensor.")

    if P.size == 0 or T.size == 0:
        raise ValueError("P and T must not be empty.")

    if not np.issubdtype(P.dtype, np.number) or not np.issubdtype(
        T.dtype, np.number
    ):
        raise TypeError("P and T must contain numeric values.")

    if P.shape[1] != T.shape[1]:
        raise ValueError(
            "Incompatible shapes: P's columns must match T's second dimension."
        )

    result = np.matmul(P, T)
    ax = sns.heatmap(result[0])

    return result, ax

