import subprocess
import os
import shutil
from glob import glob


def task_func(src_folder, dst_folder):
    def result(success, message, failed_files):
        return {
            "success": success,
            "message": message,
            "failed_files": failed_files,
        }

    if not isinstance(src_folder, (str, bytes, os.PathLike)):
        return result(False, "Invalid source folder.", [])

    if not isinstance(dst_folder, (str, bytes, os.PathLike)):
        return result(False, "Invalid destination folder.", [])

    try:
        if not os.path.isdir(src_folder):
            return result(
                False,
                "Source folder does not exist or is not a directory.",
                [],
            )

        os.makedirs(dst_folder, exist_ok=True)

        if not os.path.isdir(dst_folder):
            return result(False, "Destination path is not a directory.", [])

        source_files = [
            path
            for path in glob(os.path.join(src_folder, "*"))
            if os.path.isfile(path)
        ]
    except (OSError, TypeError, ValueError) as exc:
        return result(False, f"Could not access folders: {exc}", [])

    failed_files = []
    processes = []

    source_real = os.path.normcase(os.path.realpath(src_folder))
    destination_real = os.path.normcase(os.path.realpath(dst_folder))
    same_folder = source_real == destination_real

    for source_path in source_files:
        filename = os.path.basename(source_path)
        compressed_path = source_path + ".gz"
        destination_path = os.path.join(
            dst_folder,
            os.path.basename(compressed_path),
        )

        if os.path.lexists(compressed_path):
            failed_files.append(filename)
            continue

        if not same_folder and os.path.lexists(destination_path):
            failed_files.append(filename)
            continue

        output_file = None

        try:
            output_file = open(compressed_path, "wb")
            process = subprocess.Popen(
                ["gzip", "-c", "--", source_path],
                stdout=output_file,
                stderr=subprocess.DEVNULL,
            )
            processes.append(
                (
                    process,
                    output_file,
                    compressed_path,
                    destination_path,
                    filename,
                )
            )
        except (OSError, subprocess.SubprocessError):
            if output_file is not None:
                output_file.close()
            try:
                if os.path.lexists(compressed_path):
                    os.remove(compressed_path)
            except OSError:
                pass
            failed_files.append(filename)

    for (
        process,
        output_file,
        compressed_path,
        destination_path,
        filename,
    ) in processes:
        try:
            return_code = process.wait()
        except OSError:
            return_code = 1
        finally:
            output_file.close()

        if return_code != 0 or not os.path.isfile(compressed_path):
            failed_files.append(filename)
            try:
                if os.path.lexists(compressed_path):
                    os.remove(compressed_path)
            except OSError:
                pass
            continue

        if same_folder:
            continue

        try:
            if os.path.lexists(destination_path):
                raise FileExistsError(destination_path)
            shutil.move(compressed_path, destination_path)
        except (OSError, shutil.Error):
            failed_files.append(filename)
            try:
                if os.path.lexists(compressed_path):
                    os.remove(compressed_path)
            except OSError:
                pass

    if failed_files:
        return result(
            False,
            "Some files could not be compressed or moved.",
            failed_files,
        )

    return result(
        True,
        "All files were compressed and moved successfully.",
        [],
    )

import random
import string
import pandas as pd


def task_func(data_list, seed=0):
    rng = random.Random(seed)
    originals = list(data_list)
    modified = []

    for value in originals:
        segments = []
        start = 0

        for index, character in enumerate(value):
            if character == ",":
                if start < index:
                    segments.append((start, index))
                start = index + 1

        if start < len(value):
            segments.append((start, len(value)))

        if segments:
            segment_start, segment_end = rng.choice(segments)
            replacement = "".join(
                rng.choice(string.ascii_lowercase)
                for _ in range(segment_end - segment_start)
            )
            value = (
                value[:segment_start]
                + replacement
                + value[segment_end:]
            )

        modified.append(value)

    return pd.DataFrame(
        {
            "Original String": originals,
            "Modified String": modified,
        }
    )

import os
import glob
import shutil


def task_func(directory, archive_dir='archive'):
    if not os.path.isdir(directory):
        return False, [
            f"Source directory does not exist or is not a directory: {directory}"
        ]

    try:
        os.makedirs(archive_dir, exist_ok=True)
    except OSError as error:
        return False, [
            f"Failed to create archive directory '{archive_dir}': {error}"
        ]

    errors = []
    json_files = glob.glob(os.path.join(directory, "*.json"))

    for file_path in json_files:
        if not os.path.isfile(file_path):
            continue

        destination = os.path.join(archive_dir, os.path.basename(file_path))

        try:
            shutil.move(file_path, destination)
        except Exception as error:
            errors.append(
                f"Failed to move '{file_path}' to '{destination}': {error}"
            )

    return not errors, errors

