from collections import Counter

STOPWORDS = set(stopwords.words('english'))


def task_func(input_string):
    words = []

    for line in input_string.splitlines():
        tokens = re.findall(r"\b[a-z]+\b", line.lower())
        words.extend(word for word in tokens if word not in STOPWORDS)

    return dict(Counter(words))

import numpy as np
import random

def task_func(MIN_WORDS, MAX_WORDS, WORDS_POOL):
    if (
        isinstance(MIN_WORDS, bool)
        or isinstance(MAX_WORDS, bool)
        or not isinstance(MIN_WORDS, (int, np.integer))
        or not isinstance(MAX_WORDS, (int, np.integer))
    ):
        raise ValueError("MIN_WORDS and MAX_WORDS must be integers")

    MIN_WORDS = int(MIN_WORDS)
    MAX_WORDS = int(MAX_WORDS)

    if MIN_WORDS < 0 or MIN_WORDS > MAX_WORDS:
        raise ValueError("Invalid word count range")

    if len(WORDS_POOL) == 0 and MAX_WORDS > 0:
        raise ValueError("WORDS_POOL cannot be empty")

    length = random.randint(MIN_WORDS, MAX_WORDS)

    if length == 0:
        return ""

    first_half = [
        str(random.choice(WORDS_POOL))
        for _ in range(length // 2)
    ]

    palindrome = first_half[:]

    if length % 2:
        palindrome.append(str(random.choice(WORDS_POOL)))

    palindrome.extend(reversed(first_half))
    return " ".join(palindrome)

import pandas as pd

try:
    from sklearn.feature_selection import f_oneway
except ImportError:
    from scipy.stats import f_oneway

import matplotlib.pyplot as plt
from itertools import combinations


def task_func(data_file_path: str):
    try:
        data = pd.read_csv(data_file_path)
    except pd.errors.EmptyDataError as exc:
        raise ValueError("The CSV file is empty.") from exc

    if data.shape[1] == 0:
        raise ValueError("The CSV file contains no columns.")

    for column in data.columns:
        values = data[column]

        if values.dtype == object:
            values = values.astype(str).str.replace(",", ".", regex=False)

        data[column] = pd.to_numeric(values, errors="coerce")

    if data.dropna(how="all").empty:
        raise ValueError("The CSV file contains no valid numerical data.")

    means = data.mean()
    std_devs = data.std()

    axes = []
    for column in data.columns:
        _, ax = plt.subplots()
        values = data[column].dropna()

        if not values.empty:
            ax.hist(values)

        ax.set_title(f"Histogram of {column}")
        ax.set_xlabel(column)
        ax.set_ylabel("Frequency")
        axes.append(ax)

    anova_results = pd.DataFrame(columns=["F-value", "P-value"])

    if len(data.columns) >= 2:
        results = {}

        for first_column, second_column in combinations(data.columns, 2):
            first_values = data[first_column].dropna()
            second_values = data[second_column].dropna()
            pair_name = f"{first_column} vs {second_column}"

            if first_values.empty or second_values.empty:
                f_value = p_value = float("nan")
            else:
                try:
                    f_value, p_value = f_oneway(first_values, second_values)
                except (ValueError, ZeroDivisionError):
                    f_value = p_value = float("nan")

            results[pair_name] = {
                "F-value": f_value,
                "P-value": p_value,
            }

        anova_results = pd.DataFrame.from_dict(results, orient="index")
        anova_results.index.name = "Column pair"

    return means, std_devs, axes, anova_results

import math
import itertools
from functools import reduce

def task_func(numbers):
    total = 0.0

    for length in range(1, len(numbers) + 1):
        for combination in itertools.combinations(numbers, length):
            product = reduce(lambda x, y: x * y, combination)
            total += math.log(product)

    return float(total)

import requests
import os
import zipfile
import re
import stat
import ntpath
from urllib.parse import urlparse, unquote


def task_func(url, destination_directory, headers=None):
    if not isinstance(url, str) or not url.strip():
        raise ValueError("url must be a non-empty string")

    if destination_directory is None:
        raise ValueError("destination_directory must be provided")

    destination_directory = os.path.abspath(os.fspath(destination_directory))
    os.makedirs(destination_directory, exist_ok=True)

    filename = os.path.basename(unquote(urlparse(url).path)) or "download.zip"
    filename = re.sub(r"[^A-Za-z0-9._-]", "_", filename)
    if not filename or filename in {".", ".."}:
        filename = "download.zip"

    archive_path = os.path.join(destination_directory, filename)

    with requests.get(url, headers=headers or {}, stream=True) as response:
        response.raise_for_status()
        with open(archive_path, "wb") as archive_file:
            for chunk in response.iter_content(chunk_size=8192):
                if chunk:
                    archive_file.write(chunk)

    extracted_files = []

    with zipfile.ZipFile(archive_path, "r") as archive:
        for member in archive.infolist():
            normalized_name = member.filename.replace("\\", "/")

            if not normalized_name or normalized_name.endswith("/"):
                continue

            if "\x00" in normalized_name or normalized_name.startswith("/"):
                raise ValueError(f"Unsafe ZIP path: {member.filename}")

            if ntpath.splitdrive(normalized_name)[0]:
                raise ValueError(f"Unsafe ZIP path: {member.filename}")

            parts = [part for part in normalized_name.split("/") if part not in {"", "."}]
            if ".." in parts:
                raise ValueError(f"Unsafe ZIP path: {member.filename}")

            target_path = os.path.abspath(
                os.path.join(destination_directory, *parts)
            )

            if os.path.commonpath([destination_directory, target_path]) != destination_directory:
                raise ValueError(f"Unsafe ZIP path: {member.filename}")

            if target_path == os.path.abspath(archive_path):
                raise ValueError(
                    f"ZIP entry would overwrite the retained archive: {member.filename}"
                )

            if stat.S_ISLNK(member.external_attr >> 16):
                raise ValueError(f"Symbolic links are not allowed: {member.filename}")

            os.makedirs(os.path.dirname(target_path), exist_ok=True)
            with archive.open(member, "r") as source, open(target_path, "wb") as target:
                while True:
                    chunk = source.read(8192)
                    if not chunk:
                        break
                    target.write(chunk)

            extracted_files.append(
                os.path.relpath(target_path, destination_directory).replace(os.sep, "/")
            )

    return extracted_files

