STOPWORDS = set(stopwords.words('english'))


def task_func(text, n=2):
    if not isinstance(text, str):
        raise TypeError("text must be a string")
    if isinstance(n, bool) or not isinstance(n, int) or n <= 0:
        raise ValueError("n must be a positive integer")

    tokens = re.findall(r"\b\w+\b", text.lower())
    tokens = [token for token in tokens if token not in STOPWORDS]
    unique_tokens = list(dict.fromkeys(tokens))

    ngrams = (
        " ".join(unique_tokens[i:i + n])
        for i in range(len(unique_tokens) - n + 1)
    )

    return dict(Counter(ngrams))

import os
import shutil
import csv


def task_func(target_value='332', csv_dir='./csv_files/', processed_dir='./processed_files/', simulate=False):
    if not os.path.isdir(csv_dir):
        raise FileNotFoundError(f"CSV directory not found: {csv_dir}")

    target_value = str(target_value)
    result = {}

    for filename in sorted(os.listdir(csv_dir)):
        file_path = os.path.join(csv_dir, filename)

        if not os.path.isfile(file_path) or not filename.lower().endswith('.csv'):
            continue

        with open(file_path, 'r', newline='', encoding='utf-8') as csv_file:
            for row_index, row in enumerate(csv.reader(csv_file)):
                if row and row[0] == target_value:
                    result[filename] = row_index
                    break

        if not simulate:
            os.makedirs(processed_dir, exist_ok=True)
            shutil.move(file_path, os.path.join(processed_dir, filename))

    return result

