import os
import pandas as pd
from dateutil.parser import parse
import matplotlib.pyplot as plt

OUTPUT_DIR = './output'


def task_func(csv_path=os.path.join(OUTPUT_DIR, 'data.csv'), date_column='date'):
    df = pd.read_csv(csv_path)

    if date_column not in df.columns:
        raise KeyError(f"Column not found: {date_column}")

    def parse_date(value):
        if pd.isna(value):
            return pd.NaT
        try:
            return parse(str(value))
        except (TypeError, ValueError, OverflowError):
            return pd.NaT

    df[date_column] = df[date_column].map(parse_date)
    years = df[date_column].dropna().map(lambda date: date.year).astype(int)

    _, ax = plt.subplots()

    if years.empty:
        ax.hist([], bins=1)
    else:
        first_year = years.min()
        last_year = years.max()
        bins = [year - 0.5 for year in range(first_year, last_year + 2)]
        ax.hist(years, bins=bins)

    ax.set_xlabel("Year")
    ax.set_ylabel("Frequency")
    ax.set_title("Distribution of Dates by Year")

    return ax

import string
import random


def task_func(text, seed=None):
    if text == "":
        raise ValueError("Input text cannot be empty")

    rng = random.Random(seed)
    result = []

    for char in text:
        if char in string.ascii_letters:
            result.append(rng.choice(string.ascii_lowercase))
        elif char in string.digits:
            result.append(rng.choice(string.digits))
        elif char == " ":
            if rng.choice((True, False)):
                result.append(rng.choice(string.ascii_lowercase))
            else:
                result.append(rng.choice(string.digits))
        else:
            result.append(char)

    return "".join(result)

