import hashlib
import binascii


def task_func(salt, cursor):
    if not isinstance(salt, str):
        raise TypeError("salt must be a string")

    cursor.execute("SELECT rowid, password FROM users")
    users = cursor.fetchall()
    updated = 0

    for rowid, password in users:
        if password is None:
            continue

        digest = binascii.hexlify(
            hashlib.sha256((password + salt).encode("utf-8")).digest()
        ).decode("ascii")

        cursor.execute(
            "UPDATE users SET password = ? WHERE rowid = ?",
            (digest, rowid),
        )

        if cursor.rowcount > 0:
            updated += 1

    return updated

import re
import json
from collections import Counter


def task_func(json_str, top_n=10):
    data = json.loads(json_str)

    if not isinstance(data, dict):
        raise TypeError("json_str must represent a JSON dictionary")

    url_pattern = re.compile(r"https?://[^\s\"'<>]+", re.IGNORECASE)
    trailing_punctuation = ".,;:!?)]}"

    def iter_strings(value):
        if isinstance(value, dict):
            for key, item in value.items():
                yield from iter_strings(key)
                yield from iter_strings(item)
        elif isinstance(value, list):
            for item in value:
                yield from iter_strings(item)
        elif isinstance(value, str):
            yield value

    counts = Counter()

    for text in iter_strings(data):
        for match in url_pattern.finditer(text):
            url = match.group(0).rstrip(trailing_punctuation)
            if url:
                counts[url] += 1

    if top_n is None:
        return dict(counts.most_common())

    if top_n <= 0:
        return {}

    return dict(counts.most_common(top_n))

