import json
import re
import pandas as pd


def task_func(json_str):
    if not isinstance(json_str, str) or not json_str.strip():
        return pd.DataFrame()

    try:
        data = json.loads(json_str)
    except (TypeError, json.JSONDecodeError):
        return pd.DataFrame()

    if not isinstance(data, dict) or not data:
        return pd.DataFrame()

    number_pattern = re.compile(
        r"[-+]?(?:\d+(?:\.\d*)?|\.\d+)(?:[eE][-+]?\d+)?"
    )

    def normalize_string(value):
        stripped = value.strip()

        if number_pattern.fullmatch(stripped):
            return float(stripped) * 2

        if not number_pattern.search(value):
            return value

        return number_pattern.sub(
            lambda match: str(float(match.group()) * 2),
            value,
        )

    def normalize_value(value):
        if isinstance(value, bool):
            return value
        if isinstance(value, (int, float)):
            return float(value) * 2
        if isinstance(value, str):
            return normalize_string(value)
        if isinstance(value, list):
            return [normalize_value(item) for item in value]
        return value

    normalized = {
        key: normalize_value(value)
        for key, value in data.items()
    }

    list_values = [
        value for value in normalized.values()
        if isinstance(value, list)
    ]

    try:
        if not list_values:
            return pd.DataFrame([normalized])

        lengths = {len(value) for value in list_values}
        if len(lengths) != 1:
            return pd.DataFrame()

        row_count = next(iter(lengths))
        frame_data = {
            key: value if isinstance(value, list) else [value] * row_count
            for key, value in normalized.items()
        }
        return pd.DataFrame(frame_data)
    except (TypeError, ValueError):
        return pd.DataFrame()

