import json
import math


def task_func(decimal_value, precision=2):
    if isinstance(precision, bool) or not isinstance(precision, int):
        raise TypeError("precision must be a non-negative integer")
    if precision < 0:
        raise ValueError("precision must be non-negative")

    if isinstance(decimal_value, bool):
        raise TypeError("decimal_value must be numeric")

    try:
        value = float(decimal_value)
    except (TypeError, ValueError) as exc:
        raise TypeError("decimal_value must be numeric") from exc

    if not math.isfinite(value):
        raise ValueError("decimal_value must be finite")
    if value < 0:
        raise ValueError("decimal_value must be non-negative")

    result = round(math.sqrt(value), precision)
    return json.dumps(result, allow_nan=False)

import numpy as np
from sklearn.feature_extraction.text import TfidfVectorizer
import re
def task_func(example_str):
    if not isinstance(example_str, str) or not example_str:
        return {}

    outside_text = []
    bracket_depth = 0

    for character in example_str:
        if character == "[":
            bracket_depth += 1
        elif character == "]" and bracket_depth > 0:
            bracket_depth -= 1
        elif bracket_depth == 0:
            outside_text.append(character)

    text = "".join(outside_text)

    try:
        vectorizer = TfidfVectorizer()
        matrix = vectorizer.fit_transform([text])
    except ValueError:
        return {}

    words = vectorizer.get_feature_names_out()
    scores = np.asarray(matrix.toarray()).ravel()

    return {word: float(score) for word, score in zip(words, scores)}

