import numpy as np


def task_func(num_groups=5, data_size=5, labels=None):
    if isinstance(num_groups, (bool, np.bool_)) or not isinstance(
        num_groups, (int, np.integer)
    ):
        raise TypeError("num_groups must be an integer")
    if isinstance(data_size, (bool, np.bool_)) or not isinstance(
        data_size, (int, np.integer)
    ):
        raise TypeError("data_size must be an integer")
    if num_groups <= 0 or data_size <= 0:
        raise ValueError("num_groups and data_size must be positive")

    if labels is None:
        labels = [f"Category {i}" for i in range(1, data_size + 1)]
    else:
        if isinstance(labels, str):
            raise TypeError("labels must be a collection of labels")
        try:
            labels = list(labels)
        except TypeError as exc:
            raise TypeError("labels must be a collection of labels") from exc

        if len(labels) != data_size:
            raise ValueError("labels length must equal data_size")
        if any(isinstance(label, str) and not label for label in labels):
            raise ValueError("labels must not be empty")

        try:
            if not pd.Index(labels).is_unique:
                raise ValueError("labels must be unique")
        except (TypeError, ValueError) as exc:
            if isinstance(exc, ValueError) and str(exc) == "labels must be unique":
                raise
            raise TypeError("labels must contain hashable values") from exc

    data = pd.DataFrame(
        np.random.rand(int(num_groups), int(data_size)),
        index=[f"Group {i}" for i in range(1, int(num_groups) + 1)],
        columns=labels,
    )

    fig, ax = plt.subplots()
    bottom = np.zeros(int(num_groups))

    for column in data.columns:
        values = data[column].to_numpy()
        ax.bar(data.index, values, bottom=bottom, label=str(column))
        bottom += values

    ax.set_title("Random Data Distribution")
    ax.set_xlabel("Groups")
    ax.set_ylabel("Values")
    ax.legend()
    fig.tight_layout()

    filename = "test_plot.png"
    fig.savefig(filename)

