import pandas as pd
import csv
from difflib import ndiff


def task_func(file_path1, file_path2, delimiter=',', quotechar='"'):
    def read_lines(file_path):
        try:
            with open(file_path, 'r', encoding='utf-8', newline='') as file:
                lines = []
                for line in file:
                    if line.endswith('\r\n'):
                        line = line[:-2]
                    elif line.endswith(('\n', '\r')):
                        line = line[:-1]
                    lines.append(line)
                return lines
        except FileNotFoundError:
            raise
        except (OSError, UnicodeError) as error:
            raise Exception(f"Error reading file: {file_path}") from error

    lines1 = read_lines(file_path1)
    lines2 = read_lines(file_path2)

    if not lines1 or not lines2:
        raise ValueError("Neither file may be empty.")

    differences = []
    line_number1 = 1
    line_number2 = 1

    for difference in ndiff(lines1, lines2):
        status = difference[0]

        if status == '?':
            continue

        if status == ' ':
            line_number = line_number1
            line_number1 += 1
            line_number2 += 1
        elif status == '-':
            line_number = line_number1
            line_number1 += 1
        else:
            line_number = line_number2
            line_number2 += 1

        differences.append({
            'Line Number': line_number,
            'Status': status,
            'Content': difference[2:]
        })

    return pd.DataFrame(
        differences,
        columns=['Line Number', 'Status', 'Content']
    )

