from sklearn.cluster import KMeans
import matplotlib.pyplot as plt
import numpy as np


def task_func(df1, df2, column1="feature1", column2="feature2"):
    if column1 not in df1.columns:
        raise KeyError(f"Column {column1!r} not found in df1")
    if column2 not in df2.columns:
        raise KeyError(f"Column {column2!r} not found in df2")

    common_columns = [
        column
        for column in df1.columns.intersection(df2.columns)
        if column not in {column1, column2}
    ]

    preferred_id_columns = [
        column
        for column in common_columns
        if isinstance(column, str)
        and column.strip().lower() in {"id", "identifier", "key"}
    ]

    if preferred_id_columns:
        id_column = preferred_id_columns[0]
    elif common_columns:
        id_column = common_columns[0]
    else:
        id_column = None

    if id_column is not None:
        if df1[id_column].duplicated().any() or df2[id_column].duplicated().any():
            raise ValueError("ID columns must contain unique values")

        merged = df1[[id_column, column1]].merge(
            df2[[id_column, column2]],
            on=id_column,
            how="inner",
            validate="one_to_one",
        )
        x_values = merged[column1].to_numpy()
        y_values = merged[column2].to_numpy()
    else:
        if len(df1) != len(df2):
            raise ValueError(
                "Datasets must have equal lengths when no common ID column exists"
            )
        x_values = df1[column1].to_numpy()
        y_values = df2[column2].to_numpy()

    try:
        x_values = np.asarray(x_values, dtype=float)
        y_values = np.asarray(y_values, dtype=float)
    except (TypeError, ValueError) as exc:
        raise ValueError("Selected columns must contain numeric values") from exc

    if len(x_values) < 2:
        raise ValueError("At least two data points are required")
    if not np.isfinite(x_values).all() or not np.isfinite(y_values).all():
        raise ValueError("Selected columns must contain only finite values")

    features = np.column_stack((x_values, y_values))
    model = KMeans(n_clusters=2, n_init=10, random_state=0)
    labels = model.fit_predict(features).astype(np.int32)

    _, ax = plt.subplots()
    ax.scatter(x_values, y_values, c=labels)
    ax.set_xlabel(column1)
    ax.set_ylabel(column2)

    return labels, ax

