            raise TypeError("Each item must be an iterable of values, not a string")

        try:
            merged.extend(inner)
        except TypeError as exc:
            raise TypeError("Each item must be an iterable of values") from exc

    if not merged:
        return np.empty((0, 0), dtype=float)

    values = np.asarray(merged, dtype=object).reshape(-1, 1)

    try:
        encoder = OneHotEncoder(sparse_output=False)
    except TypeError:
        encoder = OneHotEncoder(sparse=False)

    return encoder.fit_transform(values)

