import json
import numpy as np
from collections import defaultdict
import matplotlib.pyplot as plt


def task_func(input_file):
    with open(input_file, "r", encoding="utf-8") as file:
        data = json.load(file)

    if not isinstance(data, list):
        raise TypeError("The JSON root must be a list of dictionaries.")

    values_by_key = defaultdict(list)

    for item in data:
        if not isinstance(item, dict):
            raise TypeError("Every item in the JSON list must be a dictionary.")

        for key, value in item.items():
            if isinstance(value, bool) or not isinstance(value, (int, float)):
                raise TypeError(
                    f"Value for key {key!r} must be a numeric non-boolean value."
                )

            try:
                finite = np.isfinite(value)
            except (TypeError, ValueError, OverflowError) as exc:
                raise ValueError(
                    f"Value for key {key!r} must be a finite number."
                ) from exc

            if not finite:
                raise ValueError(f"Value for key {key!r} must be finite.")

            values_by_key[key].append(value)

    result = {}
    plots = []

    for key, values in values_by_key.items():
        array = np.asarray(values, dtype=float)
        mean = float(np.mean(array))
        median = float(np.median(array))

        result[key] = {"mean": mean, "median": median}

        _, ax = plt.subplots()
        ax.bar(["mean", "median"], [mean, median])
        ax.set_title(f"Mean and Median for {key}")
        ax.set_xlabel("Statistic")
        ax.set_ylabel("Value")
        plots.append(ax)

    return result, plots

