import os
import glob
import shutil
import time

# Constants
FILE_EXTENSIONS = ['.txt', '.csv', '.xlsx', '.docx', '.pdf']


def task_func(my_path: str, days_old: int) -> str:
    if days_old < 0:
        raise ValueError("days_old must be non-negative")
    if not os.path.exists(my_path):
        raise FileNotFoundError(my_path)
    if not os.path.isdir(my_path):
        raise NotADirectoryError(my_path)

    archive_path = os.path.join(my_path, "archive")
    cutoff_time = time.time() - days_old * 24 * 60 * 60

    files_to_move = [
        path
        for path in glob.glob(os.path.join(my_path, "*"))
        if (
            os.path.isfile(path)
            and os.path.splitext(path)[1] in FILE_EXTENSIONS
            and os.path.getmtime(path) < cutoff_time
        )
    ]

    if files_to_move:
        os.makedirs(archive_path, exist_ok=True)

        for source_path in files_to_move:
            filename = os.path.basename(source_path)
            destination_path = os.path.join(archive_path, filename)

            if os.path.exists(destination_path):
                stem, extension = os.path.splitext(filename)
                counter = 1
                while os.path.exists(destination_path):
                    destination_path = os.path.join(
                        archive_path,
                        f"{stem}_{counter}{extension}",
                    )
                    counter += 1

            shutil.move(source_path, destination_path)

    return archive_path

import pandas as pd
from sklearn.feature_selection import SelectKBest, f_classif
import seaborn as sns


def task_func(df1, df2):
    if not isinstance(df1, pd.DataFrame):
        raise ValueError("df1 must be a pandas DataFrame.")

    if df1.shape[1] < 2:
        raise ValueError("df1 must contain at least two feature columns.")

    if df1.columns.duplicated().any():
        raise ValueError("df1 must not contain duplicate column names.")

    if not all(pd.api.types.is_numeric_dtype(dtype) for dtype in df1.dtypes):
        raise ValueError("All feature columns in df1 must be numeric.")

    if df1.isna().any().any():
        raise ValueError("df1 must not contain missing values.")

    if isinstance(df2, pd.DataFrame):
        if df2.shape[1] != 1:
            raise ValueError("df2 must contain exactly one target column.")
        target = df2.iloc[:, 0]
    elif isinstance(df2, pd.Series):
        target = df2
    else:
        target = pd.Series(df2)

    if len(df1) != len(target):
        raise ValueError("df1 and df2 must contain the same number of rows.")

    if target.isna().any():
        raise ValueError("df2 must not contain missing values.")

    selector = SelectKBest(score_func=f_classif, k=2)
    selector.fit(df1, target)

    selected_features = df1.columns[selector.get_support()].tolist()
    correlation_matrix = df1[selected_features].corr()
    heatmap_axes = sns.heatmap(
        correlation_matrix,
        annot=True,
        cmap="coolwarm",
    )

    return selected_features, heatmap_axes

import os
import hashlib
import json
from pathlib import Path


def task_func(directory: str) -> str:
    directory_path = Path(directory).resolve()

    if not directory_path.exists():
        raise FileNotFoundError(directory)
    if not directory_path.is_dir():
        raise NotADirectoryError(directory)

    output_path = directory_path / "hashes.json"
    hashes = {}

    for file_path in directory_path.rglob("*"):
        if file_path == output_path or not file_path.is_file():
            continue

        digest = hashlib.sha256()
        with file_path.open("rb") as file:
            while chunk := file.read(1024 * 1024):
                digest.update(chunk)

        relative_path = file_path.relative_to(directory_path).as_posix()
        hashes[relative_path] = digest.hexdigest()

    with output_path.open("w", encoding="utf-8") as file:
        json.dump(hashes, file, indent=2, sort_keys=True)
        file.write("\n")

    return str(output_path)

