import subprocess
import time
import json
import platform

LOGFILE_PATH = "logfile.log"


def task_func(interval, duration):
    if interval <= 0 or duration <= 0:
        raise ValueError("interval and duration must be greater than zero")

    is_windows = platform.system() == "Windows"
    command = "wmic cpu get loadpercentage" if is_windows else "top -bn1"
    records = []
    start_time = time.time()

    while True:
        try:
            output = subprocess.check_output(command, shell=True)
            cpu_usage = _parse_cpu_usage(output, is_windows)
        except (OSError, subprocess.SubprocessError):
            cpu_usage = 0.0

        records.append(
            {
                "timestamp": time.time(),
                "cpu_usage": cpu_usage,
            }
        )

        if time.time() - start_time >= duration:
            break

        time.sleep(interval)

    try:
        with open(LOGFILE_PATH, "w", encoding="utf-8") as logfile:
            json.dump(records, logfile)
    except IOError:
        return None

    return LOGFILE_PATH


def _parse_cpu_usage(output, is_windows):
    if isinstance(output, bytes):
        output = output.decode(errors="replace")

    if is_windows:
        for line in output.splitlines():
            value = _to_float(line.strip())
            if value is not None:
                return max(0.0, min(100.0, value))
        return 0.0

    for line in output.splitlines():
        parts = line.replace(",", " ").split()
        for index, part in enumerate(parts):
            if part.rstrip("%,").lower() in {"id", "idle"} and index > 0:
                idle = _to_float(parts[index - 1])
                if idle is not None:
                    return max(0.0, min(100.0, 100.0 - idle))

    return 0.0


def _to_float(value):
    try:
        return float(str(value).strip().rstrip("%,"))
    except (TypeError, ValueError):
        return None

