        if isinstance(value, (int, float)):
            if math.isfinite(value):
                values.append(value)
            return

        if isinstance(value, list):
            for item in value:
                collect_numeric(item)
        elif isinstance(value, dict):
            for item in value.values():
                collect_numeric(item)

    collect_numeric(current)

    if not values:
        raise ValueError("No numeric data found.")

    dataframe = pd.DataFrame({"value": np.asarray(values, dtype=float)})

    figure, axis = plt.subplots()
    sns.boxplot(data=dataframe, y="value", ax=axis)

    axis.set_title("Boxplot of Extracted Data")
    axis.set_ylabel("Value")
    figure.tight_layout()

