        )

        if os.path.lexists(destination_path):
            continue

        shutil.move(source_path, destination_path)
        moved_files.append(os.path.abspath(destination_path))

    return moved_files

import numpy as np
from sympy import symbols, solve


def task_func(precision=2, seed=0):
    if isinstance(precision, bool) or not isinstance(precision, (int, np.integer)):
        raise TypeError("precision must be a non-negative integer")
    if precision < 0:
        raise ValueError("precision must be a non-negative integer")

    np.random.seed(seed)

    a, b, c = np.random.randint(-10, 11, size=3)
    while a == 0:
        a = np.random.randint(-10, 11)

    x = symbols("x")
    roots = solve(a * x**2 + b * x + c, x)

    if len(roots) == 1:
        roots = [roots[0], roots[0]]

    solutions = []
    for root in roots[:2]:
        real_part, imaginary_part = root.evalf().as_real_imag()

        real = round(float(real_part), precision)
        imaginary = round(float(imaginary_part), precision)

        if real == 0:
            real = 0.0
        if imaginary == 0:
            imaginary = 0.0

        solutions.append(complex(real, imaginary))

    return tuple(solutions)

