def _validate_non_negative_integer(value, name):
    if isinstance(value, bool):
        raise ValueError(f'{name} must be a non-negative integer')

    if isinstance(value, float) and not value.is_integer():
        raise ValueError(f'{name} must be a non-negative integer')

    try:
        value = int(value)
    except (TypeError, ValueError) as error:
        raise ValueError(f'{name} must be a non-negative integer') from error

    if value < 0:
        raise ValueError(f'{name} must be non-negative')

    return value


def task_func(goals, penalties, csv_file_path=CSV_FILE_PATH):
    goals = _validate_non_negative_integer(goals, 'goals')
    penalties = _validate_non_negative_integer(penalties, 'penalties')

    parent_dir = os.path.dirname(csv_file_path)
    if parent_dir:
        os.makedirs(parent_dir, exist_ok=True)

    if not os.path.exists(csv_file_path) or os.path.getsize(csv_file_path) == 0:
        rows = [['team', 'goals', 'penalties']]
    else:
        with open(csv_file_path, 'r', newline='', encoding='utf-8-sig') as file:
            rows = list(csv.reader(file))

    header = rows[0]
    normalized_header = [column.strip().lower() for column in header]

    if 'goals' not in normalized_header or 'penalties' not in normalized_header:
        raise ValueError("CSV must contain 'goals' and 'penalties' columns")

    goals_index = normalized_header.index('goals')
    penalties_index = normalized_header.index('penalties')
    total_goals = 0
    total_penalties = 0

    for row_number, row in enumerate(rows[1:], start=2):
        if not row or not any(cell.strip() for cell in row):
            continue

        if len(row) <= max(goals_index, penalties_index):
            raise ValueError(f'Row {row_number} is missing required values')

        try:
            total_goals += int(row[goals_index].strip())
            total_penalties += int(row[penalties_index].strip())
        except (TypeError, ValueError) as error:
            raise ValueError(f'Invalid numeric value in row {row_number}') from error

    added_row = [''] * len(header)
    added_row[0] = 'Added values'
    added_row[goals_index] = str(goals)
    added_row[penalties_index] = str(penalties)
    rows.append(added_row)

    with open(csv_file_path, 'w', newline='', encoding='utf-8') as file:
        csv.writer(file).writerows(rows)

    return Counter({
        'goals': total_goals + goals,
        'penalties': total_penalties + penalties,
    })

