import glob
from docx import Document


def task_func(directory_path: str) -> int:
    processed_files = 0

    def protect_text(root) -> None:
        for element in root.iter():
            if isinstance(element.tag, str) and element.tag.endswith("}t"):
                if element.text:
                    element.text = re.sub(r'"', r'\\"', element.text)

    for file_path in glob.glob(f"{directory_path}/*.docx"):
        try:
            document = Document(file_path)
            processed_roots = set()

            roots = [document.element]
            for section in document.sections:
                roots.extend(
                    [
                        section.header._element,
                        section.first_page_header._element,
                        section.even_page_header._element,
                        section.footer._element,
                        section.first_page_footer._element,
                        section.even_page_footer._element,
                    ]
                )

            for root in roots:
                root_id = id(root)
                if root_id not in processed_roots:
                    processed_roots.add(root_id)
                    protect_text(root)

            document.save(file_path)
            processed_files += 1
        except Exception:
            continue

    return processed_files

