import hashlib
import re
import os

OUTPUT_DIR = './output'


def task_func(directory: str, pattern: str = r"(?<!Distillr)\\AcroTray\.exe") -> dict:
    if not os.path.exists(directory):
        raise FileNotFoundError(directory)
    if not os.path.isdir(directory):
        raise NotADirectoryError(directory)

    regex = re.compile(pattern)
    results = {}

    for root, _, filenames in os.walk(directory, followlinks=False):
        for filename in filenames:
            file_path = os.path.join(root, filename)

            if not os.path.isfile(file_path) or regex.search(file_path) is None:
                continue

            digest = hashlib.sha256()
            with open(file_path, "rb") as file:
                for chunk in iter(lambda: file.read(1024 * 1024), b""):
                    digest.update(chunk)

            results[file_path] = binascii.hexlify(digest.digest()).decode("ascii")

    return results

import re
import json
import requests


def task_func(data_url: str) -> list:
    try:
        response = requests.get(data_url)
        data = response.json()
        json_text = json.dumps(data, ensure_ascii=False)

        bracket_depth = [0] * len(json_text)
        depth = 0
        in_string = False
        escaped = False

        for index, char in enumerate(json_text):
            bracket_depth[index] = depth

            if in_string:
                if escaped:
                    escaped = False
                elif char == "\\":
                    escaped = True
                elif char == '"':
                    in_string = False
            elif char == '"':
                in_string = True
            elif char == "[":
                depth += 1
            elif char == "]":
                depth = max(0, depth - 1)

        pattern = re.compile(r'"name"\s*:\s*"((?:\\.|[^"\\])*)"')
        return [
            json.loads(f'"{match.group(1)}"')
            for match in pattern.finditer(json_text)
            if bracket_depth[match.start()] == 0
        ]

    except Exception:
        return "Invalid url input"

