import os
import shutil

# Constants
BACKUP_DIR = '/tmp/backup'


def task_func(directory):
    if not os.path.isdir(BACKUP_DIR):
        return 'Backup directory /tmp/backup does not exist. Cannot rollback update.'

    try:
        normalized_directory = os.path.normpath(directory)
        name = os.path.basename(normalized_directory)

        if not name or normalized_directory == '.':
            return 'Invalid directory path. Cannot rollback update.'

        backup_path = os.path.join(BACKUP_DIR, name)

        if not os.path.isdir(backup_path):
            return (
                f'Backup for directory {directory} does not exist. '
                'Cannot rollback update.'
            )

        target_real = os.path.realpath(normalized_directory)
        backup_real = os.path.realpath(backup_path)

        if os.path.commonpath((target_real, backup_real)) == target_real:
            return (
                'Target directory contains the backup directory. '
                'Cannot rollback update.'
            )

        if os.path.lexists(directory):
            if os.path.isdir(directory) and not os.path.islink(directory):
                shutil.rmtree(directory)
            else:
                os.remove(directory)

        shutil.copytree(backup_path, directory)
        return directory

    except (OSError, shutil.Error, TypeError, ValueError) as error:
        return f'Cannot rollback update: {error}'

