    filtered_df = df.loc[
        (df[columns[1]] > height) &
        (df[columns[2]] < weight)
    ]

    if filtered_df.empty:
        return None

    y = filtered_df[columns[0]]
    X = sm.add_constant(filtered_df[columns[1:]])

    return sm.OLS(y, X).fit()

