from typing import List, Union
import numpy as np
import scipy.fft


def task_func(data: List[Union[int, str]], repetitions: int = 1):
    if not data or repetitions <= 0:
        return {
            "mode": np.array([]),
            "count": np.array([], dtype=int),
        }

    frequencies = {}
    for value in data:
        frequencies[value] = frequencies.get(value, 0) + 1

    maximum = max(frequencies.values())
    modes = [value for value, count in frequencies.items() if count == maximum]

    try:
        modes.sort()
    except TypeError:
        modes.sort(key=lambda value: (type(value).__name__, value))

    if all(isinstance(value, (int, float, complex, np.number)) for value in data):
        scipy.fft.fft(np.tile(np.asarray(data), repetitions))

    return {
        "mode": np.asarray(modes),
        "count": np.asarray(
            [frequencies[value] * repetitions for value in modes],
            dtype=int,
        ),
    }

import numpy as np
import pandas as pd


def task_func(
    products,
    n_samples=100,
    sales_lower=50,
    sales_upper=200,
    profit_margin_min=0.1,
    profit_margin_max=0.5,
    random_seed=42,
):
    if not isinstance(products, list) or not all(
        isinstance(product, str) for product in products
    ):
        raise TypeError("products must be a list of strings")

    if isinstance(n_samples, (bool, np.bool_)) or not isinstance(
        n_samples, (int, np.integer)
    ) or n_samples <= 0:
        raise ValueError("n_samples must be a positive integer")

    numeric_types = (int, float, np.integer, np.floating)
    bounds = (
        sales_lower,
        sales_upper,
        profit_margin_min,
        profit_margin_max,
    )

    if any(
        isinstance(value, (bool, np.bool_))
        or not isinstance(value, numeric_types)
        for value in bounds
    ):
        raise TypeError("Sales and profit margin bounds must be numeric")

    if sales_lower > sales_upper:
        raise ValueError("sales_lower cannot be greater than sales_upper")

    if not products:
        return pd.DataFrame(
            columns=["product", "total_sales", "total_profit"]
        )

    rng = np.random.default_rng(random_seed)
    sampled_products = rng.choice(products, size=n_samples)

    if isinstance(sales_lower, (int, np.integer)) and isinstance(
        sales_upper, (int, np.integer)
    ):
        sales = rng.integers(
            sales_lower, sales_upper + 1, size=n_samples
        )
    else:
        sales = rng.uniform(
            sales_lower, sales_upper, size=n_samples
        )

    profit_margins = rng.uniform(
        profit_margin_min, profit_margin_max, size=n_samples
    )
    profit = sales * profit_margins

    data = pd.DataFrame(
        {
            "product": sampled_products,
            "sales": sales,
            "profit": profit,
        }
    )

    return (
        data.groupby("product", as_index=False)
        .agg(
            total_sales=("sales", "sum"),
            total_profit=("profit", "sum"),
        )
        .sort_values("total_profit", ascending=False)
        .reset_index(drop=True)
    )

