import importlib
from pkgutil import iter_modules


def task_func(package_name):
    try:
        package = importlib.import_module(package_name)
    except ImportError as exc:
        raise ImportError(
            f"Unable to import package '{package_name}'. "
            f"Install it with: pip install {package_name}"
        ) from exc

    package_paths = getattr(package, "__path__", None)
    if package_paths is None:
        raise ImportError(
            f"'{package_name}' is not a package. "
            f"Install the package with: pip install {package_name}"
        )

    module_names = set()

    try:
        for package_path in package_paths:
            package_path = os.fspath(package_path)

            if package_path not in sys.path:
                sys.path.append(package_path)

            for module_info in iter_modules([package_path]):
                module_names.add(module_info.name)
    except (OSError, ImportError) as exc:
        raise ImportError(
            f"Unable to enumerate package '{package_name}'. "
            f"Install it with: pip install {package_name}"
        ) from exc

    return sorted(module_names)

