from sklearn.cluster import KMeans
import matplotlib.pyplot as plt
import pandas as pd


def task_func(df, n_clusters=3, random_state=None, n_init=10):
    if not isinstance(df, pd.DataFrame):
        raise TypeError("df must be a pandas DataFrame")
    if df.empty:
        raise ValueError("df must not be empty")

    if isinstance(n_clusters, bool) or not isinstance(n_clusters, int):
        raise TypeError("n_clusters must be a positive integer")
    if n_clusters <= 0:
        raise ValueError("n_clusters must be positive")

    if isinstance(n_init, bool) or (
        not isinstance(n_init, int) and n_init != "auto"
    ):
        raise TypeError("n_init must be a positive integer or 'auto'")
    if isinstance(n_init, int) and n_init <= 0:
        raise ValueError("n_init must be positive")

    numeric_columns = df.select_dtypes(include="number").columns.tolist()
    if len(numeric_columns) < 2:
        raise ValueError("df must contain at least two numeric columns")

    numeric_data = df[numeric_columns]
    if numeric_data.isna().any().any():
        raise ValueError("numeric columns must not contain missing values")

    unique_points = df.drop_duplicates(keep="first").copy()
    if n_clusters > len(unique_points):
        raise ValueError(
            "n_clusters cannot exceed the number of unique points"
        )

    def point_key(row):
        result = []
        for value in row:
            missing = pd.isna(value)
            if isinstance(missing, bool) and missing:
                result.append(None)
            else:
                try:
                    hash(value)
                    result.append(value)
                except TypeError:
                    result.append(repr(value))
        return tuple(result)

    counts = Counter(point_key(row) for _, row in df.iterrows())
    duplicate_counts = Counter(
        point for point, count in counts.items() if count > 1
    )

    model = KMeans(
        n_clusters=n_clusters,
        random_state=random_state,
        n_init=n_init,
    )
    labels = model.fit_predict(unique_points[numeric_columns])
    unique_points["cluster"] = labels

    _, axes = plt.subplots()
    axes.scatter(
        unique_points[numeric_columns[0]],
        unique_points[numeric_columns[1]],
        c=labels,
        cmap="viridis",
    )
    axes.set_xlabel(numeric_columns[0])
    axes.set_ylabel(numeric_columns[1])
    axes.set_title("KMeans Clusters")

    return duplicate_counts, unique_points, axes

