import numpy as np
from scipy.optimize import curve_fit


def task_func(x, y, labels):
    import matplotlib.pyplot as plt

    def model(x_values, a, b, c):
        return a * np.exp(-b * x_values) + c

    if isinstance(labels, str):
        labels = [labels]
    else:
        try:
            labels = list(labels)
        except TypeError as exc:
            raise ValueError("labels must be an iterable.") from exc

    if not labels:
        raise ValueError("At least one label is required.")

    dataset_count = len(labels)

    def normalize(values, name):
        try:
            array = np.asarray(values, dtype=float)
        except (TypeError, ValueError):
            array = None

        if dataset_count == 1:
            if array is not None and array.ndim == 1:
                return [array]
            if array is not None and array.ndim == 2 and array.shape[0] == 1:
                return [array[0]]
            raise ValueError(f"{name} must contain one one-dimensional dataset.")

        if array is not None and array.ndim == 2:
            if array.shape[0] != dataset_count:
                raise ValueError(
                    f"{name} must contain {dataset_count} datasets."
                )
            return [array[i] for i in range(dataset_count)]

        try:
            datasets = list(values)
        except TypeError as exc:
            raise ValueError(
                f"{name} must contain {dataset_count} datasets."
            ) from exc

        if len(datasets) != dataset_count:
            raise ValueError(f"{name} must contain {dataset_count} datasets.")

        try:
            return [np.asarray(dataset, dtype=float) for dataset in datasets]
        except (TypeError, ValueError) as exc:
            raise ValueError(f"{name} must contain numeric data.") from exc

    x_datasets = normalize(x, "x")
    y_datasets = normalize(y, "y")

    figure, axis = plt.subplots()

    for index, (x_data, y_data, label) in enumerate(
        zip(x_datasets, y_datasets, labels), start=1
    ):
        if x_data.ndim != 1 or y_data.ndim != 1:
            raise ValueError(f"Dataset {index} must be one-dimensional.")

        if len(x_data) != len(y_data):
            raise ValueError(
                f"Dataset {index} has mismatched x and y lengths."
            )

        if len(x_data) < 3:
            raise ValueError(
                f"Dataset {index} must contain at least three points."
            )

        if not np.all(np.isfinite(x_data)) or not np.all(np.isfinite(y_data)):
            raise ValueError(f"Dataset {index} contains non-finite values.")

        x_min = np.min(x_data)
        x_max = np.max(x_data)
        x_range = x_max - x_min

        if x_range == 0:
            raise ValueError(f"Dataset {index} has constant x values.")

        y_min = np.min(y_data)
        y_max = np.max(y_data)

        initial_guess = [
            y_max - y_min,
            1.0 / x_range,
            y_min,
        ]

        try:
            parameters, _ = curve_fit(
                model,
                x_data,
                y_data,
                p0=initial_guess,
                maxfev=10000,
            )
        except (RuntimeError, TypeError, ValueError, OverflowError) as exc:
            raise ValueError(
                f"Could not fit the exponential curve for dataset {index}."
            ) from exc

        x_curve = np.linspace(x_min, x_max, 500)
        y_curve = model(x_curve, *parameters)
        axis.plot(x_curve, y_curve, label=label)

    axis.set_xlabel("x")
    axis.set_ylabel("y")
    axis.legend()
    axis.grid(True)
    figure.tight_layout()

    return figure

