import heapq
from scipy import stats


def task_func(df, col1, col2, N=10):
    if col1 not in df.columns or col2 not in df.columns:
        raise ValueError("Specified columns are not in the DataFrame.")

    if N <= 1:
        raise ValueError("N must be greater than 1.")

    records = [
        (abs(value1 - value2), value1, value2)
        for value1, value2 in zip(df[col1], df[col2])
    ]

    largest = heapq.nlargest(N, records, key=lambda record: record[0])
    values1 = [record[1] for record in largest]
    values2 = [record[2] for record in largest]

    return float(stats.ttest_ind(values1, values2).pvalue)

