import requests
import json
import pandas as pd
import seaborn as sns
import matplotlib.pyplot as plt
from urllib.parse import urlparse

# Constants
HEADERS = {
    'accept': 'application/json'
}


def task_func(url, parameters):
    """Retrieve API data and display a correlation heatmap."""
    if not isinstance(url, str) or not url.strip():
        raise Exception("URL must be a non-empty string.")

    parsed_url = urlparse(url)
    if parsed_url.scheme not in {"http", "https"} or not parsed_url.netloc:
        raise Exception("Invalid URL.")

    if parameters is None:
        parameters = {}
    elif not hasattr(parameters, "items"):
        raise Exception("Parameters must be dictionary-like.")

    try:
        response = requests.get(
            url,
            params=parameters,
            headers=HEADERS
        )
        response.raise_for_status()
        payload = response.json()
    except Exception as exc:
        raise Exception("Unable to access or parse the API response.") from exc

    try:
        if payload is None or payload == {} or payload == []:
            raise Exception("The API returned empty data.")

        if isinstance(payload, dict):
            for key in ("data", "results", "items"):
                if key in payload:
                    payload = payload[key]
                    break

        if payload is None or payload == {} or payload == []:
            raise Exception("The API returned empty data.")

        if isinstance(payload, list):
            if not all(isinstance(item, dict) for item in payload):
                raise Exception("The API returned invalid data.")
            dataframe = pd.DataFrame(payload)
        elif isinstance(payload, dict):
            if all(isinstance(value, (list, tuple)) for value in payload.values()):
                dataframe = pd.DataFrame(payload)
            else:
                dataframe = pd.DataFrame([payload])
        else:
            raise Exception("The API returned invalid data.")
    except Exception as exc:
        raise Exception("The API data cannot be converted to a DataFrame.") from exc

    if dataframe.empty:
        raise Exception("The resulting DataFrame is empty.")

    numeric_data = dataframe.select_dtypes(include="number")
    if numeric_data.empty:
        raise Exception("The data contains no numerical characteristics.")

    correlation = numeric_data.corr()
    if correlation.empty or correlation.isna().all().all():
        raise Exception("The numerical data cannot produce a valid correlation matrix.")

    _, axes = plt.subplots()
    sns.heatmap(
        correlation,
        annot=True,
        cmap="coolwarm",
        vmin=-1,
        vmax=1,
        ax=axes
    )
    axes.set_title("Correlation Heatmap")
    plt.show()

    return dataframe, axes

import random
import re


def task_func(text, seed=None):
    rng = random.Random(seed)

    def scramble(match):
        word = match.group(0)
        if len(word) <= 3:
            return word

        middle = list(word[1:-1])
        rng.shuffle(middle)
        return word[0] + "".join(middle) + word[-1]

    return re.sub(r"\b\w+\b", scramble, text)

import subprocess
import os
import time
import glob


def task_func(r_script_path: str, output_path: str, duration: int) -> (bool, str):
    success_message = "File generated successfully within the specified duration."
    failure_message = "File not generated within the specified duration."

    if duration < 0:
        return False, failure_message

    existing_files = {}
    for path in glob.glob(output_path):
        try:
            stat = os.stat(path)
            existing_files[path] = (
                stat.st_dev,
                stat.st_ino,
                stat.st_size,
                stat.st_mtime_ns,
            )
        except OSError:
            continue

    try:
        process = subprocess.Popen(["Rscript", r_script_path])
    except OSError:
        return False, failure_message

    start_time = time.monotonic()
    deadline = start_time + duration
    first_check = True

    def output_was_generated() -> bool:
        for path in glob.glob(output_path):
            try:
                stat = os.stat(path)
                current_state = (
                    stat.st_dev,
                    stat.st_ino,
                    stat.st_size,
                    stat.st_mtime_ns,
                )
            except OSError:
                continue

            if path not in existing_files or current_state != existing_files[path]:
                return True

        return False

    try:
        while True:
            if not first_check and time.monotonic() > deadline:
                return False, failure_message

            if output_was_generated():
                return True, success_message

            first_check = False
            now = time.monotonic()

            if now >= deadline:
                return False, failure_message

            if process.poll() is not None:
                return False, failure_message

            time.sleep(min(0.1, deadline - now))
    finally:
        if process.poll() is None:
            process.terminate()
            try:
                process.wait(timeout=1)
            except subprocess.TimeoutExpired:
                process.kill()
                process.wait()

