import os
import glob
from pathlib import Path
import zipfile


def task_func(source_directory, target_directory, zip_name):
    source_path = Path(source_directory)

    if not source_path.is_dir():
        raise OSError(f"Source directory does not exist: {source_directory}")

    target_path = Path(target_directory)
    target_path.mkdir(parents=True, exist_ok=True)

    zip_path = (target_path / f"{zip_name}.zip").resolve()
    valid_extensions = {".txt", ".docx", ".xlsx", ".csv"}

    with zipfile.ZipFile(zip_path, "w", compression=zipfile.ZIP_DEFLATED) as archive:
        for file_name in glob.glob(str(source_path / "**" / "*"), recursive=True):
            file_path = Path(file_name)

            if (
                file_path.is_file()
                and file_path.suffix in valid_extensions
                and file_path.resolve() != zip_path
            ):
                archive.write(
                    file_path,
                    arcname=file_path.relative_to(source_path),
                )

    return str(zip_path)

import numpy as np
import matplotlib.pyplot as plt
import seaborn as sns


def task_func(array, features=None, seed=None):
    array = np.asarray(array)

    if array.ndim != 2 or array.size == 0 or array.shape[1] == 0:
        raise ValueError("array must be a non-empty 2-dimensional array")

    n_columns = array.shape[1]

    if features is None:
        labels = [str(i) for i in range(1, n_columns + 1)]
    else:
        try:
            labels = list(features)
        except TypeError as exc:
            raise ValueError(
                "features must match the number of columns in array"
            ) from exc

        if len(labels) != n_columns:
            raise ValueError("features must match the number of columns in array")

    rng = np.random.default_rng(seed)
    permutation = rng.permutation(n_columns)

    shuffled_array = array[:, permutation]
    shuffled_labels = [labels[index] for index in permutation]

    return sns.heatmap(
        shuffled_array,
        xticklabels=shuffled_labels,
    )

import pandas as pd
import numpy as np
import itertools
import numbers


def task_func(data_list=[('a', 1, 2.1), ('b', 2, 3.2), ('c', 3, 4.3), ('d', 4, 5.4), ('e', 5, 6.5)]):
    if not data_list:
        return pd.DataFrame(columns=['Mean Value'])

    max_length = max(len(item) for item in data_list)
    values_by_position = [[] for _ in range(max_length)]

    for item in data_list:
        for position, value in enumerate(item):
            if (
                isinstance(value, numbers.Number)
                and not isinstance(value, (bool, np.bool_))
                and not pd.isna(value)
            ):
                values_by_position[position].append(value)

    means = [
        np.mean(values) if values else np.nan
        for values in values_by_position
    ]

    return pd.DataFrame(
        {'Mean Value': means},
        index=[f'Position {i}' for i in range(max_length)]
    )

import os
import glob
from collections import Counter


def task_func(directory, extensions=[".txt", ".docx", ".xlsx", ".csv"], keep_zero=True):
    if not os.path.isdir(directory):
        raise OSError(f"Directory does not exist: {directory}")

    extensions = list(dict.fromkeys(extensions))
    extension_set = set(extensions)
    counts = Counter({extension: 0 for extension in extensions}) if keep_zero else Counter()

    for root, _, files in os.walk(directory):
        for filename in files:
            filepath = os.path.join(root, filename)
            if os.path.isfile(filepath):
                extension = os.path.splitext(filename)[1]
                if extension in extension_set:
                    counts[extension] += 1

    return counts

