import numpy as np
import math
import random
from random import uniform
def task_func(radius, num_points):
    if isinstance(radius, bool) or not isinstance(
        radius, (int, float, np.integer, np.floating)
    ):
        raise TypeError("radius must be a real number")

    radius = float(radius)
    if not math.isfinite(radius) or radius < 0:
        raise ValueError("radius must be finite and non-negative")

    if isinstance(num_points, bool) or not isinstance(num_points, (int, np.integer)):
        raise TypeError("num_points must be a non-negative integer")
    if num_points < 0:
        raise ValueError("num_points must be non-negative")

    out = []
    for _ in range(int(num_points)):
        theta = uniform(0.0, 2.0 * math.pi)
        distance = radius * math.sqrt(uniform(0.0, 1.0))
        x = distance * math.cos(theta)
        y = distance * math.sin(theta)

        norm = math.hypot(x, y)
        if norm > radius:
            scale = radius / norm
            x *= scale
            y *= scale

        out.append((x, y))

    return (out,)

