import inspect
import pandas as pd
def task_func(f_list, file_path):
    import os

    if not isinstance(f_list, list) or not f_list:
        raise ValueError("f_list must be a non-empty list of functions")

    if not all(inspect.isfunction(func) for func in f_list):
        raise ValueError("f_list must contain only functions")

    if not isinstance(file_path, (str, bytes, os.PathLike)):
        raise ValueError("file_path must be a valid path")

    try:
        file_path = os.fspath(file_path)
    except TypeError as exc:
        raise ValueError("file_path must be a valid path") from exc

    if not file_path or (isinstance(file_path, str) and "\x00" in file_path):
        raise ValueError("file_path must be a valid path")

    rows = []

    for func in f_list:
        signature = inspect.signature(func)

        defaults = {
            name: repr(parameter.default)
            for name, parameter in signature.parameters.items()
            if parameter.default is not inspect.Parameter.empty
        }

        annotations = {
            name: repr(annotation)
            for name, annotation in func.__annotations__.items()
        }

        rows.append(
            {
                "Function Name": func.__name__,
                "Number of Arguments": len(signature.parameters),
                "Defaults": repr(defaults),
                "Annotations": repr(annotations),
                "Is Lambda": func.__name__ == "<lambda>",
            }
        )

    dataframe = pd.DataFrame(
        rows,
        columns=[
            "Function Name",
            "Number of Arguments",
            "Defaults",
            "Annotations",
            "Is Lambda",
        ],
    )

    try:
        dataframe.to_csv(file_path, index=False)
    except OSError as exc:
        raise IOError(f"Error writing to {file_path!r}") from exc

    return None

import pandas as pd
from sklearn.preprocessing import StandardScaler
from sklearn.decomposition import PCA
from numbers import Integral


def task_func(data, n_components=2):
    if not isinstance(data, pd.DataFrame):
        raise ValueError("Input data must be a pandas DataFrame.")

    if data.empty:
        raise ValueError("Input data must not be empty.")

    if not all(pd.api.types.is_numeric_dtype(dtype) for dtype in data.dtypes):
        raise ValueError("Input data must contain only numeric values.")

    if isinstance(n_components, bool) or not isinstance(n_components, Integral):
        raise ValueError("n_components must be a positive integer.")

    if n_components <= 0:
        raise ValueError("n_components must be a positive integer.")

    if n_components > data.shape[1]:
        raise ValueError(
            "n_components cannot be greater than the number of columns."
        )

    if n_components > data.shape[0]:
        raise ValueError(
            "n_components cannot be greater than the number of rows."
        )

    scaled_data = StandardScaler().fit_transform(data)
    transformed_data = PCA(n_components=n_components).fit_transform(scaled_data)

    return pd.DataFrame(transformed_data, index=data.index)

import os
import pandas as pd
import re


def task_func(file_path: str) -> pd.DataFrame:
    columns = ["Timestamp", "Level", "Message"]

    if not os.path.exists(file_path):
        raise FileNotFoundError(file_path)

    pattern = re.compile(
        r"^(\d{4}-\d{2}-\d{2} \d{2}:\d{2}:\d{2}\.\d{6})\s+-\s+(.+?)\s+-\s+(.*)$"
    )

    records = []

    with open(file_path, "r", encoding="utf-8") as log_file:
        for line in log_file:
            match = pattern.match(line.rstrip("\r\n"))
            if match:
                records.append(
                    {
                        "Timestamp": match.group(1),
                        "Level": match.group(2).strip(),
                        "Message": match.group(3),
                    }
                )

    return pd.DataFrame(records, columns=columns)

