import xlwt
import os
import pandas as pd
import json


def task_func(json_str, filename, sheet_name="sheet1"):
    if not isinstance(json_str, (str, bytes, bytearray)):
        raise TypeError("json_str must be a string, bytes, or bytearray")

    try:
        data = json.loads(json_str)
    except (json.JSONDecodeError, UnicodeDecodeError) as exc:
        raise ValueError("json_str is not valid JSON") from exc

    if isinstance(data, list):
        if not data:
            dataframe = pd.DataFrame()
        elif all(isinstance(item, dict) for item in data):
            dataframe = pd.DataFrame(data)
        else:
            dataframe = pd.DataFrame({"value": data})
    elif isinstance(data, dict):
        dataframe = pd.DataFrame([data])
    else:
        dataframe = pd.DataFrame({"value": [data]})

    try:
        output_path = os.path.abspath(filename)
        workbook = xlwt.Workbook()
        worksheet = workbook.add_sheet(sheet_name)

        for column_index, column in enumerate(dataframe.columns):
            worksheet.write(0, column_index, str(column))

        for row_index, row in enumerate(dataframe.itertuples(index=False, name=None), start=1):
            for column_index, value in enumerate(row):
                if isinstance(value, (dict, list)):
                    value = json.dumps(value, ensure_ascii=False)
                worksheet.write(row_index, column_index, value)

        workbook.save(output_path)
        return output_path
    except Exception as exc:
        raise Exception("Failed to write the Excel file") from exc

from itertools import zip_longest
from scipy.spatial import distance


def task_func(points):
    def normalize(point):
        if isinstance(point, (tuple, list)):
            coordinates = tuple(point)
        else:
            coordinates = (point,)

        if len(coordinates) == 1:
            return coordinates * 2
        if len(coordinates) == 2:
            return coordinates
        raise ValueError("Each point must contain one or two coordinates.")

    normalized_points = [normalize(point) for point in points]

    return [
        float(distance.euclidean(first, second))
        for first, second in zip(
            normalized_points, normalized_points[1:]
        )
    ]

import pandas as pd
from scipy.stats import chi2_contingency


def task_func(df, columns=['A', 'B', 'C'], larger=50, equal=900):
    if len(columns) != 3:
        raise ValueError("Exactly three columns must be specified.")

    if any(column not in df.columns for column in columns):
        raise ValueError("Specified columns must be contained in the DataFrame.")

    filtered = df[
        (df[columns[1]] > larger)
        & (df[columns[2]] == equal)
    ]

    if filtered.empty:
        raise ValueError("Insufficient data for the chi-square test.")

    contingency_table = pd.crosstab(
        filtered[columns[0]],
        filtered[columns[1]],
    )

    _, p_value, _, _ = chi2_contingency(contingency_table)
    return float(p_value)

