import pandas as pd
import numpy as np
from random import choice

# Constants
DATA_TYPES = [str, int, float, list, tuple, dict, set]


def task_func(rows, columns):
    if isinstance(rows, bool) or not isinstance(rows, (int, np.integer)):
        raise TypeError("rows must be a non-negative integer")
    if isinstance(columns, bool) or not isinstance(columns, (int, np.integer)):
        raise TypeError("columns must be a non-negative integer")
    if rows < 0 or columns < 0:
        raise ValueError("rows and columns must be non-negative")

    def generate_value(data_type):
        if data_type is str:
            return "".join(
                np.random.choice(list("abcdefghijklmnopqrstuvwxyz"), size=5)
            )

        if data_type is int:
            return int(np.random.randint(0, 10))

        if data_type is float:
            return float(np.random.randint(0, 10))

        length = int(np.random.randint(1, 6))

        if data_type is list:
            return np.random.randint(0, 10, size=length).tolist()

        if data_type is tuple:
            return tuple(np.random.randint(0, 10, size=length).tolist())

        if data_type is dict:
            keys = np.random.choice(10, size=length, replace=False).tolist()
            values = np.random.randint(0, 10, size=length).tolist()
            return dict(zip(keys, values))

        if data_type is set:
            return set(np.random.choice(10, size=length, replace=False).tolist())

        raise TypeError(f"Unsupported data type: {data_type}")

    data = {
        f"col{column}": [
            generate_value(choice(DATA_TYPES)) for _ in range(rows)
        ]
        for column in range(columns)
    }

    if columns == 0:
        return pd.DataFrame(index=range(rows))

    return pd.DataFrame(data)

