import os
import shutil


def task_func(path, delimiter="/"):
    if not isinstance(path, str) or not isinstance(delimiter, str):
        raise ValueError("path and delimiter must be strings")

    if not path or not delimiter or not path.strip():
        raise ValueError("path and delimiter must not be empty")

    if "\0" in path or "\0" in delimiter:
        raise ValueError("path contains a null character")

    is_absolute = delimiter == os.sep and path.startswith(os.sep)

    if is_absolute:
        path_without_root = path[len(os.sep):]
        if not path_without_root or path_without_root.startswith(os.sep):
            raise ValueError("path contains an invalid component")
        path = path_without_root
    elif path.startswith(delimiter) or path.endswith(delimiter):
        raise ValueError("path contains an invalid component")

    components = path.split(delimiter)

    if any(
        not component
        or component.isspace()
        or component in (".", "..")
        for component in components
    ):
        raise ValueError("path contains an invalid component")

    separators = {os.sep}
    if os.altsep:
        separators.add(os.altsep)

    for component in components:
        for separator in separators:
            if separator != delimiter and separator in component:
                raise ValueError("path contains an inconsistent separator")

    current_path = os.sep if is_absolute else ""
    result = []

    for component in components:
        current_path = os.path.join(current_path, component)

        if not os.path.exists(current_path):
            raise FileNotFoundError(current_path)

        if not os.path.isdir(current_path):
            raise ValueError("path components must be directories")

        usage = shutil.disk_usage(current_path)
        result.append(
            (
                component,
                {
                    "total": usage.total,
                    "used": usage.used,
                    "free": usage.free,
                },
            )
        )

    return result

