from datetime import datetime
import pandas as pd
import numpy as np
import matplotlib.pyplot as plt


def task_func(start_time, end_time, step, amplitude, period, seed=0):
    start = pd.Timestamp(start_time)
    end = pd.Timestamp(end_time)

    start = (
        start.tz_localize("UTC")
        if start.tzinfo is None
        else start.tz_convert("UTC")
    )
    end = (
        end.tz_localize("UTC")
        if end.tzinfo is None
        else end.tz_convert("UTC")
    )

    if start > end:
        raise ValueError("start_time must not be later than end_time")

    try:
        step_delta = pd.to_timedelta(step)
    except (TypeError, ValueError):
        raise ValueError("step must be a valid positive time interval")

    if pd.isna(step_delta) or step_delta <= pd.Timedelta(0):
        raise ValueError("step must be positive")

    if isinstance(period, str):
        try:
            period_delta = pd.to_timedelta(period)
        except (TypeError, ValueError):
            raise ValueError("period must be a valid positive time interval")

        if pd.isna(period_delta) or period_delta <= pd.Timedelta(0):
            raise ValueError("period must be positive")

        period_seconds = period_delta.total_seconds()
    else:
        if (
            not np.isscalar(period)
            or isinstance(period, bool)
            or not np.isfinite(period)
            or period <= 0
        ):
            raise ValueError("period must be a positive number")

        period_seconds = float(period)

    if (
        not np.isscalar(amplitude)
        or isinstance(amplitude, bool)
        or not np.isfinite(amplitude)
    ):
        raise ValueError("amplitude must be a finite number")

    timestamps = pd.date_range(
        start=start,
        end=end,
        freq=step_delta,
        tz="UTC",
    )

    elapsed_seconds = (timestamps - timestamps[0]).total_seconds()
    values = float(amplitude) * np.sin(
        2 * np.pi * elapsed_seconds / period_seconds
    )

    data = pd.DataFrame(
        {
            "Timestamp": timestamps,
            "Value": values,
        }
    )

    _, ax = plt.subplots()
    ax.plot(data["Timestamp"], data["Value"])
    ax.set_xlabel("Timestamp")
    ax.set_ylabel("Value")
    ax.set_title("Time Series with Seasonality")

    return ax

