def task_func(file_name):
    with open(file_name, "r", newline="", encoding="utf-8") as file:
        reader = csv.reader(file)
        try:
            column_names = next(reader)
        except StopIteration:
            return {}

        counters = [collections.Counter() for _ in column_names]

        for row in reader:
            for index, value in enumerate(row[:len(counters)]):
                counters[index][value] += 1

    result = {}
    for name, counter in zip(column_names, counters):
        if counter:
            maximum = max(counter.values())
            result[name] = min(
                value for value, count in counter.items()
                if count == maximum
            )

    return result

