import subprocess
import psutil
import time
import os


def task_func(script_path: str, timeout=10) -> dict:
    if not os.path.exists(script_path):
        raise FileNotFoundError(f"Script not found: {script_path}")

    try:
        timeout = float(timeout)
    except (TypeError, ValueError) as exc:
        raise ValueError("timeout must be a non-negative finite number") from exc

    if timeout < 0 or timeout != timeout or timeout == float("inf"):
        raise ValueError("timeout must be a non-negative finite number")

    cpu_usage = 0.0
    memory_usage = 0
    process = None

    try:
        process = subprocess.Popen(["bash", script_path])
        monitored_process = psutil.Process(process.pid)
        monitored_process.cpu_percent(interval=None)
        start_time = time.monotonic()

        while process.poll() is None:
            remaining = timeout - (time.monotonic() - start_time)
            if remaining <= 0:
                break

            try:
                if not monitored_process.is_running():
                    break

                if monitored_process.status() == psutil.STATUS_ZOMBIE:
                    break

                interval = min(0.1, remaining)
                cpu_usage += monitored_process.cpu_percent(interval=interval)
                memory_usage += monitored_process.memory_info().rss

            except (
                psutil.NoSuchProcess,
                psutil.ZombieProcess,
                psutil.AccessDenied,
            ):
                break

    finally:
        if process is not None:
            if process.poll() is None:
                try:
                    process.terminate()
                    process.wait(timeout=1)
                except (subprocess.TimeoutExpired, OSError):
                    try:
                        process.kill()
                    except OSError:
                        pass

            try:
                process.wait()
            except OSError:
                pass

    return {
        "CPU Usage": cpu_usage,
        "Memory Usage": memory_usage,
    }

