import matplotlib.pyplot as plt


def task_func(df):
    import numpy as np
    from pandas.api.types import is_numeric_dtype

    result = df.copy()
    numeric_positions = [
        position
        for position, dtype in enumerate(df.dtypes)
        if is_numeric_dtype(dtype)
    ]

    _, ax = plt.subplots()

    if not numeric_positions:
        return result, ax

    numeric_df = df.iloc[:, numeric_positions].astype(float)
    values = numeric_df.to_numpy()
    values[~np.isfinite(values)] = np.nan

    counts = np.sum(~np.isnan(values), axis=0)
    sums = np.nansum(values, axis=0)
    means = np.divide(
        sums,
        counts,
        out=np.zeros(values.shape[1], dtype=float),
        where=counts != 0,
    )

    for column_index in range(values.shape[1]):
        missing = np.isnan(values[:, column_index])
        values[missing, column_index] = means[column_index]

    if values.shape[0] > 0:
        normalized = MinMaxScaler().fit_transform(values)
    else:
        normalized = values

    for position, column_index in enumerate(numeric_positions):
        result.iloc[:, column_index] = normalized[:, position]

    if normalized.shape[0] > 0:
        ax.boxplot(
            [normalized[:, index] for index in range(normalized.shape[1])],
            labels=[df.columns[index] for index in numeric_positions],
        )

    return result, ax

