import pandas as pd
import re

# Function to replace acronyms in DataFrame
def task_func(data, mapping):
    if not isinstance(data, pd.DataFrame):
        raise TypeError("data must be a pandas DataFrame")

    if not isinstance(mapping, dict):
        raise TypeError("mapping must be a dictionary")

    if any(not isinstance(key, str) for key in mapping):
        raise TypeError("All mapping keys must be strings")

    if any(not isinstance(value, str) for value in mapping.values()):
        raise TypeError("All mapping values must be strings")

    result = data.copy()

    keys = sorted(
        (key for key in mapping if key),
        key=len,
        reverse=True,
    )

    if not keys:
        return result

    pattern = re.compile(
        r"(?<!\w)(?:" + "|".join(re.escape(key) for key in keys) + r")(?!\w)"
    )

    def replace_cell(value):
        if isinstance(value, str):
            return pattern.sub(lambda match: mapping[match.group(0)], value)
        return value

    return result.apply(lambda column: column.map(replace_cell))

