    samples = np.random.normal(loc=mean, scale=std_dev, size=n)

    x = np.linspace(mean - 4 * std_dev, mean + 4 * std_dev, 500)
    pdf = stats.norm.pdf(x, loc=mean, scale=std_dev)

    if n > 0:
        plt.hist(samples, bins=30, density=True, alpha=0.6, label="Samples")
    plt.plot(x, pdf, "r-", linewidth=2, label="Normal PDF")
    plt.xlabel("Value")
    plt.ylabel("Density")
    plt.title("Normal Distribution Samples")
    plt.legend()
    plt.show()

    return samples

