def task_func(array: list, random_seed: int = 42) -> (pd.DataFrame, np.ndarray):
    """Convert a 2D list to a DataFrame and reduce it to two PCA components."""
    if not isinstance(array, list) or not array:
        raise ValueError("array must be a non-empty 2D list")

    if not all(isinstance(row, (list, tuple)) for row in array):
        raise ValueError("array must be a 2D list")

    row_lengths = {len(row) for row in array}
    if len(row_lengths) != 1 or not row_lengths or next(iter(row_lengths)) == 0:
        raise ValueError("array must be a non-empty rectangular 2D list")

    dataframe = pd.DataFrame(array)

    if dataframe.shape[0] < 2 or dataframe.shape[1] < 2:
        raise ValueError(
            "array must contain at least two rows and two columns for PCA"
        )

    if not all(pd.api.types.is_numeric_dtype(dtype) for dtype in dataframe.dtypes):
        raise ValueError("array must contain only numeric values")

    if dataframe.isna().any().any():
        raise ValueError("array must not contain missing values")

    transformed = PCA(
        n_components=2,
        random_state=random_seed,
    ).fit_transform(dataframe.to_numpy())

    return dataframe, transformed

