import pandas as pd
import matplotlib.pyplot as plt
from statsmodels.tsa.seasonal import seasonal_decompose
import numpy as np


def task_func(df, freq='D', decomposition_model='multiplicative'):
    if not isinstance(df, pd.DataFrame):
        raise ValueError("'df' must be a pandas DataFrame")

    if "value" not in df.columns:
        raise ValueError("DataFrame must contain a 'value' column")

    if df.empty:
        raise ValueError("DataFrame must not be empty")

    if not isinstance(freq, str) or not freq.strip():
        raise ValueError("'freq' must be a valid frequency string")

    try:
        offset = pd.tseries.frequencies.to_offset(freq)
    except (TypeError, ValueError, OverflowError) as exc:
        raise ValueError("'freq' must be a valid frequency string") from exc

    if decomposition_model not in {"additive", "multiplicative"}:
        raise ValueError(
            "'decomposition_model' must be 'additive' or 'multiplicative'"
        )

    values = df["value"]

    if isinstance(values, pd.DataFrame):
        raise ValueError("'value' must identify a single column")

    if (
        not pd.api.types.is_numeric_dtype(values)
        or pd.api.types.is_bool_dtype(values)
    ):
        raise ValueError("'value' must contain numeric data")

    try:
        numeric_values = values.to_numpy(dtype=float)
    except (TypeError, ValueError) as exc:
        raise ValueError("'value' must contain numeric data") from exc

    if not np.isfinite(numeric_values).all():
        raise ValueError("'value' contains missing or non-finite values")

    if decomposition_model == "multiplicative" and (numeric_values <= 0).any():
        raise ValueError(
            "Multiplicative decomposition requires strictly positive values"
        )

    if isinstance(df.index, pd.RangeIndex) or pd.api.types.is_numeric_dtype(df.index):
        raise ValueError("DataFrame index must be datetime-based")

    try:
        index = (
            df.index
            if isinstance(df.index, pd.DatetimeIndex)
            else pd.to_datetime(df.index, errors="raise")
        )
    except (TypeError, ValueError) as exc:
        raise ValueError("DataFrame index must contain valid timestamps") from exc

    if index.has_duplicates or not index.is_monotonic_increasing:
        raise ValueError("Datetime index must be sorted and unique")

    series = pd.Series(numeric_values, index=index, name="value")

    try:
        regular_series = series.resample(freq).asfreq()
    except (TypeError, ValueError) as exc:
        raise ValueError("'freq' must be a valid frequency string") from exc

    if regular_series.isna().any():
        raise ValueError(
            "The data must contain observations at every timestamp for the given frequency"
        )

    rule = getattr(offset, "rule_code", getattr(offset, "name", "")).upper()
    base_rule = rule.split("-")[0]
    multiplier = abs(getattr(offset, "n", 1))

    periods = {
        "S": 86400,
        "T": 1440,
        "MIN": 1440,
        "H": 24,
        "D": 7,
        "B": 5,
        "W": 52,
        "M": 12,
        "ME": 12,
        "MS": 12,
        "Q": 4,
        "QE": 4,
        "QS": 4,
        "A": 12,
        "Y": 12,
        "YE": 12,
        "YS": 12,
    }

    if base_rule not in periods:
        raise ValueError(f"Unsupported frequency: {freq!r}")

    period = periods[base_rule] // multiplier

    if period < 2 or len(regular_series) < 2 * period:
        raise ValueError("Insufficient data for seasonal decomposition")

    try:
        result = seasonal_decompose(
            regular_series,
            model=decomposition_model,
            period=period,
        )
    except (TypeError, ValueError) as exc:
        raise ValueError(f"Unable to decompose the time series: {exc}") from exc

    figure = result.plot()
    axes = figure.axes[0]

    return result, axes

