import os
import shutil


def task_func(directory):
    if not os.path.isdir(directory):
        raise ValueError("directory must be an existing directory")

    for name in os.listdir(directory):
        source = os.path.join(directory, name)

        if not os.path.isfile(source):
            continue

        _, extension = os.path.splitext(name)
        extension = extension[1:].lower() if extension else "no_extension"
        destination_dir = os.path.join(directory, extension)

        try:
            os.makedirs(destination_dir, exist_ok=True)
        except OSError:
            continue

        destination = os.path.join(destination_dir, name)

        if os.path.lexists(destination):
            stem, suffix = os.path.splitext(name)
            counter = 1

            while True:
                candidate = os.path.join(
                    destination_dir, f"{stem}_{counter}{suffix}"
                )
                if not os.path.lexists(candidate):
                    destination = candidate
                    break
                counter += 1

        try:
            shutil.move(source, destination)
        except OSError:
            continue

    return None

