import re
from datetime import time


def task_func(logs: list):
    """Return error occurrence times and their average."""
    time_pattern = re.compile(
        r"(?<!\d)([01]\d|2[0-3]):([0-5]\d)(?::([0-5]\d))?(?!\d)"
    )

    error_times = []
    total_seconds = 0

    for log in logs:
        if not isinstance(log, str) or not re.search(r"\berror\b", log, re.IGNORECASE):
            continue

        match = time_pattern.search(log)
        if not match:
            continue

        hours = int(match.group(1))
        minutes = int(match.group(2))
        seconds = int(match.group(3) or 0)

        error_times.append(time(hours, minutes, seconds))
        total_seconds += hours * 3600 + minutes * 60 + seconds

    if not error_times:
        return {"list": [], "time": None}

    average_seconds = round(total_seconds / len(error_times))
    average_time = time(
        average_seconds // 3600,
        (average_seconds % 3600) // 60,
        average_seconds % 60,
    )

    return {"list": error_times, "time": average_time}

