import os
import re
from pathlib import Path


def task_func(dir_path: str, predicates: list) -> dict:
    directory = Path(dir_path)

    if not directory.exists() or not directory.is_dir():
        raise FileNotFoundError(dir_path)

    try:
        predicate_iter = iter(predicates)
    except TypeError:
        raise ValueError("No valid predicates were provided")

    regex_type = type(re.compile(""))
    normalized = []
    seen = set()

    for predicate in predicate_iter:
        if isinstance(predicate, regex_type):
            if not isinstance(predicate.pattern, str) or not predicate.pattern:
                continue
            key = ("regex", predicate.pattern, predicate.flags)
            evaluator = predicate.search
        elif isinstance(predicate, str):
            if not predicate:
                continue
            try:
                compiled = re.compile(predicate)
            except re.error:
                continue
            key = ("regex", compiled.pattern, compiled.flags)
            evaluator = compiled.search
        elif callable(predicate):
            key = ("callable", id(predicate))
            evaluator = predicate
        else:
            continue

        if key not in seen:
            seen.add(key)
            normalized.append(evaluator)

    if not normalized:
        raise ValueError("No valid predicates were provided")

    result = {}
    for item in directory.iterdir():
        result[item.name] = [
            bool(predicate(item.name)) for predicate in normalized
        ]

    return result

import os
import shutil


def task_func(src_dir, dest_dir, extension):
    if not isinstance(extension, str) or not extension.strip():
        raise ValueError("extension must be a non-empty string")

    src_dir = os.fspath(src_dir)
    dest_dir = os.fspath(dest_dir)

    if not os.path.isdir(src_dir):
        raise NotADirectoryError(src_dir)

    extension = extension.strip()
    if not extension.startswith("."):
        extension = "." + extension

    os.makedirs(dest_dir, exist_ok=True)

    if os.path.realpath(src_dir) == os.path.realpath(dest_dir):
        return {"files_moved": 0}

    files_moved = 0

    with os.scandir(src_dir) as entries:
        for entry in entries:
            if entry.is_file(follow_symlinks=False) and entry.name.endswith(extension):
                shutil.move(entry.path, os.path.join(dest_dir, entry.name))
                files_moved += 1

    return {"files_moved": files_moved}

