import random
import re


def task_func(target_words, n_sentences, vocabulary):
    if n_sentences < 0:
        raise ValueError("n_sentences must not be negative")
    if not vocabulary:
        raise ValueError("vocabulary must not be empty")

    patterns = []
    for target in target_words:
        parts = target.strip().split()
        if parts:
            patterns.append(r"\s+".join(re.escape(part) for part in parts))

    matcher = None
    if patterns:
        patterns.sort(key=len, reverse=True)
        matcher = re.compile(
            r"(?<!\S)(?:" + "|".join(patterns) + r")(?!\S)",
            re.IGNORECASE,
        )

    sentences = []
    for _ in range(n_sentences):
        sentence = " ".join(random.choices(vocabulary, k=10)).lower()
        if matcher:
            sentence = matcher.sub(
                lambda match: re.sub(r"\s+", "_", match.group()),
                sentence,
            )
        sentences.append(sentence)

    return sentences

