import pandas as pd
import random


def task_func(data, columns=['Name', 'Age', 'Occupation'], fill_missing=False, num_range=(0, 100), seed=None):
    if len(num_range) != 2 or num_range[0] > num_range[1]:
        raise ValueError("num_range must contain two ordered bounds")

    column_count = len(columns)
    rows = []

    for row in data:
        values = list(row)[:column_count]
        values.extend([None] * (column_count - len(values)))
        rows.append(values)

    df = pd.DataFrame(rows, columns=columns)

    if fill_missing:
        rng = random.Random(seed)

        for index in range(column_count):
            series = df.iloc[:, index]

            if pd.api.types.is_numeric_dtype(series) and series.isna().any():
                missing = series.isna()
                replacement = [
                    rng.randint(num_range[0], num_range[1])
                    for _ in range(int(missing.sum()))
                ]
                series = series.copy()
                series.loc[missing] = replacement
                df.iloc[:, index] = series

    return df

