import math


def task_func(
    epoch_milliseconds,
    random_seed=0,
    products=["Product1", "Product2", "Product3", "Product4", "Product5"],
):
    if isinstance(epoch_milliseconds, bool):
        raise ValueError("epoch_milliseconds must be a finite number")

    try:
        timestamp = float(epoch_milliseconds)
    except (TypeError, ValueError, OverflowError):
        raise ValueError("epoch_milliseconds must be a finite number")

    if not math.isfinite(timestamp) or timestamp < 0:
        raise ValueError("epoch_milliseconds must be a non-negative finite number")

    if not hasattr(products, "__len__") or len(products) != 5:
        raise ValueError("products must contain exactly five items")

    if not all(isinstance(product, str) for product in products):
        raise ValueError("each product must be a string")

    try:
        start_datetime = datetime.fromtimestamp(timestamp / 1000)
    except (OverflowError, OSError, ValueError):
        raise ValueError("invalid epoch timestamp")

    current_datetime = datetime.now()

    if start_datetime.date() > current_datetime.date():
        raise ValueError("epoch timestamp cannot be in the future")

    rng = random.Random(random_seed)
    rows = []
    current_date = start_datetime.date()
    end_date = current_datetime.date()

    while current_date <= end_date:
        date_value = datetime.combine(current_date, datetime.min.time())

        for product in products:
            rows.append(
                {
                    "Product": product,
                    "Date": date_value,
                    "Sales": rng.randint(10, 50),
                }
            )

        current_date += timedelta(days=1)

    return pd.DataFrame(rows, columns=["Product", "Date", "Sales"])

