    with open(file_path, "r", encoding="utf-8", newline="") as csv_file:
        for row in csv.reader(csv_file):
            for cell in row:
                for match in pattern.finditer(cell):
                    value = match.group(0)
                    if value:
                        counts[value] += 1

    return dict(counts)

