import hashlib
import random
import struct

KEYS = ['470FC614', '4A0FC614', '4B9FC614', '4C8FC614', '4D7FC614']


def task_func(hex_keys=KEYS, seed=42):
    """Return the MD5 hash of a float decoded from a randomly selected key."""
    decoded_keys = []

    for key in hex_keys:
        if not isinstance(key, str):
            raise ValueError("Keys must be hexadecimal strings")

        try:
            key_bytes = bytes.fromhex(key)
        except ValueError as exc:
            raise ValueError("Keys must be valid hexadecimal strings") from exc

        if len(key_bytes) != 4 or len(key) != 8:
            raise ValueError("Keys must contain exactly 8 hexadecimal characters")

        decoded_keys.append(key_bytes)

    selected_bytes = random.Random(seed).choice(decoded_keys)
    float_value = struct.unpack("!f", selected_bytes)[0]
    return hashlib.md5(str(float_value).encode("utf-8")).hexdigest()

