import socket
import select
import queue
from datetime import datetime, timedelta


def task_func(
    server_address="localhost", server_port=12345, buffer_size=1024, run_duration=5
):
    if buffer_size <= 0:
        raise ValueError("buffer_size must be positive")

    start_time = datetime.now()
    server_socket = None
    clients = set()
    outgoing = {}
    send_buffers = {}

    def close_client(client):
        clients.discard(client)
        outgoing.pop(client, None)
        send_buffers.pop(client, None)
        try:
            client.close()
        except OSError:
            pass

    try:
        server_socket = socket.socket(socket.AF_INET, socket.SOCK_STREAM)
        server_socket.setsockopt(socket.SOL_SOCKET, socket.SO_REUSEADDR, 1)
        server_socket.bind((server_address, server_port))
        server_socket.listen()
        server_socket.setblocking(False)

        end_time = start_time + timedelta(seconds=max(0, run_duration))

        while datetime.now() < end_time:
            remaining = (end_time - datetime.now()).total_seconds()
            if remaining <= 0:
                break

            writable = [
                client
                for client in clients
                if client in send_buffers
                or not outgoing[client].empty()
            ]
            monitored = [server_socket, *clients]

            try:
                readable, writable_ready, exceptional = select.select(
                    monitored,
                    writable,
                    monitored,
                    remaining,
                )
            except InterruptedError:
                continue
            except OSError:
                break

            if server_socket in exceptional:
                break

            if server_socket in readable:
                while True:
                    try:
                        client, _ = server_socket.accept()
                        client.setblocking(False)
                        clients.add(client)
                        outgoing[client] = queue.Queue()
                    except BlockingIOError:
                        break
                    except OSError:
                        break

            for client in exceptional:
                if client is not server_socket:
                    close_client(client)

            for client in readable:
                if client is server_socket or client not in clients:
                    continue

                try:
                    data = client.recv(buffer_size)
                    if not data:
                        close_client(client)
                        continue

                    timestamp = datetime.now().isoformat().encode("utf-8")
                    outgoing[client].put(data + timestamp)
                except BlockingIOError:
                    continue
                except (ConnectionResetError, OSError):
                    close_client(client)

            for client in writable_ready:
                if client not in clients:
                    continue

                try:
                    if client not in send_buffers:
                        try:
                            send_buffers[client] = bytearray(
                                outgoing[client].get_nowait()
                            )
                        except queue.Empty:
                            continue

                    sent = client.send(send_buffers[client])
                    del send_buffers[client][:sent]

                    if not send_buffers[client]:
                        send_buffers.pop(client, None)
                except BlockingIOError:
                    continue
                except (BrokenPipeError, ConnectionResetError, OSError):
                    close_client(client)

    except (OSError, ValueError) as error:
        return f"Server failed to start: {error}"
    finally:
        for client in list(clients):
            close_client(client)

        if server_socket is not None:
            try:
                server_socket.close()
            except OSError:
                pass

    elapsed = (datetime.now() - start_time).total_seconds()
    return f"Server ran for {elapsed:.2f} seconds"

import numpy as np
import pandas as pd
import matplotlib.pyplot as plt


def task_func(N=100, CATEGORIES=["A", "B", "C", "D", "E"], seed=42):
    if isinstance(N, (bool, np.bool_)) or not isinstance(N, (int, np.integer)):
        raise TypeError("N must be a non-negative integer")
    if N < 0:
        raise ValueError("N must be non-negative")

    categories = list(CATEGORIES)

    if N > 0 and not categories:
        raise ValueError("CATEGORIES must not be empty when N is positive")

    if len(set(categories)) != len(categories):
        raise ValueError("CATEGORIES must contain unique values")

    rng = np.random.default_rng(seed)

    x = rng.random(N)
    y = rng.random(N)

    if N < len(categories):
        selected_categories = rng.choice(
            categories, size=N, replace=False
        ).tolist()
    elif categories:
        selected_categories = categories.copy()
        selected_categories.extend(
            rng.choice(
                categories,
                size=N - len(categories),
                replace=True,
            ).tolist()
        )
        rng.shuffle(selected_categories)
    else:
        selected_categories = []

    df = pd.DataFrame(
        {
            "x": x,
            "y": y,
            "category": selected_categories,
        }
    )

    _, ax = plt.subplots()

    if categories:
        cmap = plt.get_cmap("tab20", len(categories))
        color_map = {
            category: cmap(index)
            for index, category in enumerate(categories)
        }

        ax.scatter(
            df["x"],
            df["y"],
            c=[color_map[category] for category in selected_categories],
        )

        handles = [
            plt.Line2D(
                [],
                [],
                marker="o",
                linestyle="",
                color=color_map[category],
                label=str(category),
            )
            for category in categories
        ]
        ax.legend(handles=handles, title="category")

    ax.set_xlabel("x")
    ax.set_ylabel("y")

    return df, ax

import pandas as pd
import numpy as np
import codecs
import re
import datetime


def task_func(start_year=1980, end_year=2000, email_domain='example.com',
              latin_names=['Sopetón', 'Méndez', 'Gómez', 'Pérez', 'Muñoz'],
              other_names=['Smith', 'Johnson', 'Williams', 'Brown', 'Jones'],
              rng_seed=None):
    """Generate a DataFrame containing 100 randomly generated users."""

    if isinstance(start_year, (bool, np.bool_)) or not isinstance(
        start_year, (int, np.integer)
    ):
        raise TypeError("start_year must be an integer")

    if isinstance(end_year, (bool, np.bool_)) or not isinstance(
        end_year, (int, np.integer)
    ):
        raise TypeError("end_year must be an integer")

    if start_year > end_year:
        raise ValueError("start_year must not exceed end_year")

    if not isinstance(email_domain, str) or not email_domain:
        raise ValueError("email_domain must be a non-empty string")

    names = list(latin_names) + list(other_names)

    if not names:
        raise ValueError("At least one name must be provided")

    if not all(isinstance(name, str) for name in names):
        raise TypeError("All names must be strings")

    def correct_encoding(name):
        current = name

        for _ in range(3):
            try:
                corrected = codecs.decode(current.encode("latin1"), "utf-8")
            except (UnicodeEncodeError, UnicodeDecodeError):
                break

            if corrected == current:
                break

            old_markers = current.count("Ã") + current.count("Â") + current.count("â")
            new_markers = corrected.count("Ã") + corrected.count("Â") + corrected.count("â")

            if new_markers >= old_markers:
                break

            current = corrected

        return current

    def is_leap_year(year):
        return year % 400 == 0 or (year % 4 == 0 and year % 100 != 0)

    def days_in_month(year, month):
        if month == 2:
            return 29 if is_leap_year(year) else 28
        return 30 if month in (4, 6, 9, 11) else 31

    def format_date(year, month, day):
        return f"{year:04d}-{month:02d}-{day:02d} 00:00:00"

    rng = np.random.default_rng(rng_seed)
    records = []

    for record_id in range(1, 101):
        name = correct_encoding(
            names[int(rng.integers(0, len(names)))]
        )
        year = int(rng.integers(start_year, end_year + 1))
        month = int(rng.integers(1, 13))
        day = int(rng.integers(1, days_in_month(year, month) + 1))

        if 1 <= year <= 9999:
            date_of_birth = datetime.datetime(year, month, day)
        else:
            date_of_birth = format_date(year, month, day)

        records.append({
            "ID": record_id,
            "Name": name,
            "Date of Birth": date_of_birth,
            "Email": f"{name.lower()}{year}@{email_domain}",
        })

    return pd.DataFrame(
        records,
        columns=["ID", "Name", "Date of Birth", "Email"]
    )

