import pandas as pd
import numpy as np
from statsmodels.tsa.seasonal import seasonal_decompose


def task_func(start_date='2016-01-01', periods=24, freq='M', model='additive'):
    if isinstance(periods, bool) or not isinstance(periods, (int, np.integer)):
        raise ValueError("periods must be a positive integer")
    if periods <= 0:
        raise ValueError("periods must be a positive integer")
    if model not in {'additive', 'multiplicative'}:
        raise ValueError("model must be 'additive' or 'multiplicative'")

    index = pd.date_range(start=start_date, periods=int(periods), freq=freq)
    frequency = str(freq).upper()

    if frequency.startswith(('M', 'BM', 'BME', 'MS')):
        seasonal_period = 12
    elif frequency.startswith('Q'):
        seasonal_period = 4
    elif frequency.startswith('W'):
        seasonal_period = 52
    elif frequency.startswith(('D', 'B')):
        seasonal_period = 7
    elif frequency.startswith('H'):
        seasonal_period = 24
    else:
        seasonal_period = 12

    time = np.arange(int(periods))
    trend = 100 + 2.5 * time
    seasonal_pattern = np.sin(2 * np.pi * time / seasonal_period)
    noise = 0.03 * np.cos(2 * np.pi * time / 5)

    if model == 'multiplicative':
        sales = trend * (1 + 0.15 * seasonal_pattern + noise)
    else:
        sales = trend + 12 * seasonal_pattern + 2 * noise

    sales_series = pd.Series(sales, index=index, name='sales')
    decomposition = seasonal_decompose(
        sales_series,
        model=model,
        period=seasonal_period
    )

    return {
        'trend': decomposition.trend,
        'seasonal': decomposition.seasonal,
        'residual': decomposition.resid
    }

