def task_func(df):
    if df.empty or "Title" not in df.columns or "Content" not in df.columns:
        raise ValueError(
            "DataFrame must be non-empty and contain 'Title' and 'Content' columns"
        )

    def is_missing(value):
        if value is None:
            return True
        try:
            result = value != value
            return bool(result)
        except (TypeError, ValueError):
            return value.__class__.__name__ in {"NAType", "NaTType"}

    frequencies = {}

    for title, content in zip(df["Title"], df["Content"]):
        if is_missing(title):
            continue

        if not re.search(r"(like|what)", str(title), flags=re.IGNORECASE):
            continue

        if is_missing(content):
            continue

        words = re.findall(
            r"[^\W_]+",
            str(content).lower(),
            flags=re.UNICODE,
        )

        for word in words:
            frequencies[word] = frequencies.get(word, 0) + 1

    return frequencies

