import numpy as np
from sklearn.decomposition import PCA
import matplotlib.pyplot as plt


def task_func(P, T, tensor_shape=(3, 3, 3)):
    if not isinstance(P, (np.ndarray, np.matrix)):
        raise TypeError("P must be a NumPy array or matrix.")
    if not isinstance(T, (np.ndarray, np.matrix)):
        raise TypeError("T must be a NumPy array or matrix.")

    P = np.asarray(P)
    T = np.asarray(T)

    if P.ndim != 2:
        raise ValueError("P must be two-dimensional.")
    if T.ndim != 3:
        raise ValueError("T must be three-dimensional.")

    try:
        tensor_shape = tuple(tensor_shape)
    except TypeError as exc:
        raise ValueError("tensor_shape must contain exactly three dimensions.") from exc

    if len(tensor_shape) != 3:
        raise ValueError("tensor_shape must contain exactly three dimensions.")
    if any(
        isinstance(dim, bool) or not isinstance(dim, (int, np.integer)) or dim <= 0
        for dim in tensor_shape
    ):
        raise ValueError("tensor_shape dimensions must be positive integers.")
    if T.shape != tensor_shape:
        raise ValueError("T.shape must match tensor_shape.")
    if P.shape[1] != tensor_shape[0]:
        raise ValueError("P columns must match the first dimension of T.")
    if P.shape[0] < 2:
        raise ValueError("P must contain at least two rows.")
    if tensor_shape[1] * tensor_shape[2] < 2:
        raise ValueError("The product must contain at least two features.")

    product = P @ T.reshape(tensor_shape[0], -1)
    pca_result = PCA(n_components=2).fit_transform(product)

    _, ax = plt.subplots()
    ax.scatter(pca_result[:, 0], pca_result[:, 1])
    ax.set_title("PCA Result Visualization")
    ax.set_xlabel("Principal Component 1")
    ax.set_ylabel("Principal Component 2")

    return pca_result, ax

import pandas as pd
from sklearn.linear_model import LinearRegression

DATA = {
    "Area_String": ["1,000", "2,000", "3,000", "4,000", "5,000"],
    "Price": [100, 200, 300, 400, 500],
}


def task_func(area_string, data=DATA):
    if not isinstance(data, dict):
        raise ValueError("data must be a dictionary")

    required_keys = {"Area_String", "Price"}
    missing_keys = required_keys - data.keys()
    if missing_keys:
        raise ValueError(
            f"Missing required keys: {', '.join(sorted(missing_keys))}"
        )

    areas = data["Area_String"]
    prices = data["Price"]

    try:
        area_count = len(areas)
        price_count = len(prices)
    except TypeError as exc:
        raise ValueError("Area and price data must be sequences") from exc

    if area_count == 0:
        raise ValueError("Training data must not be empty")
    if area_count != price_count:
        raise ValueError("Area and price data must have equal lengths")

    def parse_area(value):
        if value is None or (
            isinstance(value, str) and not value.strip()
        ):
            raise ValueError("Area must be a non-empty numeric value")

        try:
            numeric_value = float(str(value).replace(",", "").strip())
        except (TypeError, ValueError) as exc:
            raise ValueError(f"Invalid area value: {value!r}") from exc

        if not pd.notna(numeric_value) or not pd.np.isfinite(numeric_value):
            raise ValueError(f"Invalid area value: {value!r}")

        return numeric_value

    try:
        area_values = [parse_area(value) for value in areas]
        price_values = pd.to_numeric(
            pd.Series(prices), errors="raise"
        ).tolist()
    except (TypeError, ValueError) as exc:
        raise ValueError("Training data contains invalid values") from exc

    if any(
        not pd.notna(value) or not pd.np.isfinite(value)
        for value in price_values
    ):
        raise ValueError("Price values must be finite and non-null")

    model = LinearRegression()
    model.fit(
        pd.DataFrame({"Area": area_values}),
        price_values,
    )

    requested_area = parse_area(area_string)
    prediction = model.predict(
        pd.DataFrame({"Area": [requested_area]})
    )[0]

    return float(prediction)

