    except (OSError, TypeError, ValueError) as error:
        warnings.warn(
            f"Could not create destination directory '{DEST_DIR}': {error}"
        )
        return transferred_files

    try:
        entries = list(os.scandir(SOURCE_DIR))
    except (OSError, TypeError, ValueError) as error:
        warnings.warn(f"Could not read source directory '{SOURCE_DIR}': {error}")
        return transferred_files

    for entry in entries:
        try:
            if not entry.is_file(follow_symlinks=False):
                continue

            if os.path.splitext(entry.name)[1].lower() not in normalized_extensions:
                continue

            destination_path = os.path.join(DEST_DIR, entry.name)

            if os.path.realpath(entry.path) == os.path.realpath(destination_path):
                raise shutil.SameFileError(entry.path, destination_path)

            if os.path.exists(destination_path):
                raise FileExistsError(
                    f"Destination file already exists: {destination_path}"
                )

            shutil.move(entry.path, destination_path)
            transferred_files.append(entry.name)

        except (OSError, shutil.Error, TypeError, ValueError) as error:
            warnings.warn(f"Could not transfer '{entry.name}': {error}")

    return transferred_files

