import numpy as np
import pandas as pd
from scipy.stats import linregress


def task_func(df):
    if not isinstance(df, pd.DataFrame):
        raise TypeError("df must be a pandas DataFrame")

    if df.shape[1] < 2:
        raise ValueError("DataFrame must contain at least two columns")

    x_series = df.iloc[:, 0]
    y_series = df.iloc[:, 1]

    if not pd.api.types.is_numeric_dtype(x_series):
        raise TypeError("The first column must be numeric")

    if not pd.api.types.is_numeric_dtype(y_series):
        raise TypeError("The second column must be numeric")

    try:
        x = x_series.astype(float).to_numpy()
        y = y_series.astype(float).to_numpy()
    except (TypeError, ValueError) as exc:
        raise TypeError("The first two columns must contain real numeric values") from exc

    valid = np.isfinite(x) & np.isfinite(y)

    if valid.sum() < 2:
        raise ValueError("At least two valid observations are required")

    if np.unique(x[valid]).size < 2:
        raise ValueError("The independent variable must not be constant")

    slope, intercept, *_ = linregress(x[valid], y[valid])

    predictions = np.full(len(df), np.nan, dtype=float)
    finite_x = np.isfinite(x)
    predictions[finite_x] = intercept + slope * x[finite_x]

    df["predicted"] = predictions
    return df

