def task_func(data, labels):
    """Plot data series with cycling colors and return the Axes object."""
    _, ax = plt.subplots()

    labels = [] if labels is None else list(labels)
    label_count = len(labels)

    for index, (series, label) in enumerate(
        zip_longest(data, labels, fillvalue=None)
    ):
        if series is None:
            continue

        if index >= len(COLORS) + label_count:
