import subprocess
import csv
import glob
import random
import os


def task_func(file):
    created_files = []

    try:
        file = os.fsdecode(os.fspath(file))

        if not os.path.isfile(file):
            return []

        if os.path.splitext(file)[1].lower() != ".csv":
            return []

        directory = os.path.abspath(os.path.dirname(file) or ".")
        source = os.path.abspath(file)

        while True:
            token = f"{os.getpid()}_{random.randrange(10**9)}"
            prefix = os.path.join(directory, f"split_{token}_")
            if not glob.glob(prefix + "*"):
                break

        subprocess.run(
            ["split", "-l", "1000", "--", source, prefix],
            check=True,
            stdout=subprocess.PIPE,
            stderr=subprocess.PIPE,
        )

        created_files = sorted(
            path for path in glob.glob(prefix + "*")
            if os.path.isfile(path)
        )

        for path in created_files:
            with open(path, "r", newline="", encoding="utf-8") as source_file:
                rows = list(csv.reader(source_file, strict=True))

            random.shuffle(rows)

            with open(path, "w", newline="", encoding="utf-8") as target_file:
                csv.writer(target_file).writerows(rows)

        return created_files

    except Exception:
        for path in set(created_files + glob.glob(locals().get("prefix", "") + "*")):
            try:
                if os.path.isfile(path):
                    os.remove(path)
            except OSError:
                pass
        return []

