import re
import os
from pathlib import Path
import csv


def task_func(directory: str, pattern: str = r'^(.*?)-\d+\.csv$') -> list:
    directory_path = Path(directory)

    if not directory_path.exists():
        raise FileNotFoundError(directory)
    if not directory_path.is_dir():
        raise NotADirectoryError(directory)

    regex = re.compile(pattern)

    if regex.groups < 1:
        raise ValueError("Pattern must contain at least one capture group")

    new_files = []

    for source in directory_path.iterdir():
        if not source.is_file():
            continue

        match = regex.match(source.name)
        if match is None:
            continue

        destination = directory_path / f"{match.group(1)}.csv"

        if source == destination:
            continue

        destination.write_bytes(source.read_bytes())
        new_files.append(destination.name)

    return new_files

