import re
import pandas as pd


def task_func(df: pd.DataFrame, column_name: str, pattern: str) -> pd.DataFrame:
    if pattern == "":
        return df.copy()

    regex = re.compile(pattern)

    def reverse_matching_words(value):
        if not isinstance(value, str):
            return value

        words = value.split()
        matching_indices = [
            index for index, word in enumerate(words) if regex.search(word)
        ]
        matching_words = [
            words[index] for index in matching_indices
        ][::-1]

        for index, word in zip(matching_indices, matching_words):
            words[index] = word

        return " ".join(words)

    result = df.copy()
    result[column_name] = result[column_name].apply(reverse_matching_words)
    return result

