import json
import os
import re


def task_func(
    file_path,
    attribute,
    INPUT_JSON={
        "type": "object",
        "properties": {
            "name": {"type": str},
            "age": {"type": int},
            "email": {"type": str},
        },
        "required": ["name", "age", "email"],
    },
    EMAIL_REGEX=r"^[a-z0-9]+[\._]?[a-z0-9]+[@]\w+[.]\w{2,3}$",
):
    try:
        if not os.path.isfile(file_path):
            raise ValueError("The specified file does not exist.")

        with open(file_path, "r", encoding="utf-8") as file:
            data = json.load(file)
    except ValueError:
        raise
    except (OSError, UnicodeDecodeError, json.JSONDecodeError) as exc:
        raise ValueError("Unable to read or parse the JSON file.") from exc

    if INPUT_JSON.get("type") == "object" and type(data) is not dict:
        raise ValueError("The JSON root must be an object.")

    properties = INPUT_JSON.get("properties", {})
    required = INPUT_JSON.get("required", [])

    missing = [field for field in required if field not in data]
    if missing:
        raise ValueError(
            f"Missing required attributes: {', '.join(map(str, missing))}"
        )

    for field, schema in properties.items():
        if field not in data:
            continue

        expected_type = schema.get("type")
        if expected_type is not None and type(data[field]) is not expected_type:
            raise ValueError(f"Invalid type for attribute: {field}")

    if "email" in data:
        if type(data["email"]) is not str or re.fullmatch(
            EMAIL_REGEX, data["email"]
        ) is None:
            raise ValueError("Invalid email format.")

    if attribute not in data:
        raise ValueError(f"Attribute not found: {attribute}")

    if attribute not in properties:
        raise ValueError(f"Attribute is not defined in the schema: {attribute}")

    return data[attribute]

