import ssl
import os
import hashlib


def task_func(client_socket, cert_file, key_file, buffer_size=1024):
    secured_socket = None

    try:
        if buffer_size <= 0:
            raise ValueError("buffer_size must be greater than zero")

        context = ssl.SSLContext(ssl.PROTOCOL_TLS_SERVER)
        context.load_cert_chain(certfile=cert_file, keyfile=key_file)

        secured_socket = context.wrap_socket(
            client_socket,
            server_side=True,
        )

        requested_path = secured_socket.recv(buffer_size).decode("utf-8").strip()

        if not requested_path:
            raise ValueError("Client did not send a file path")

        if not os.path.isfile(requested_path):
            result = "File not found"
        else:
            file_hash = hashlib.sha256()

            with open(requested_path, "rb") as file:
                while chunk := file.read(buffer_size):
                    file_hash.update(chunk)

            result = file_hash.hexdigest()

        secured_socket.sendall(result.encode("utf-8"))
        return result

    except Exception as error:
        result = f"Error: {error}"

        if secured_socket is not None:
            try:
                secured_socket.sendall(result.encode("utf-8"))
            except Exception:
                pass

        return result

