import pandas as pd


def task_func(url='http://example.com'):
    response = requests.get(url)
    response.raise_for_status()

    try:
        soup = BeautifulSoup(response.text, "html.parser")
    except Exception as exc:
        raise ValueError("Page content cannot be parsed") from exc

    table = soup.find("table")
    if table is None:
        raise ValueError("No table found on the page")

    def clean_text(element):
        return " ".join(element.get_text(" ", strip=True).split())

    headers = []
    for row in table.find_all("tr"):
        header_cells = row.find_all("th")
        if header_cells:
            headers = [clean_text(cell) for cell in header_cells]
            break

    rows = []
    for row in table.find_all("tr"):
        data_cells = row.find_all("td")
        if data_cells:
            rows.append([clean_text(cell) for cell in data_cells])

    if not rows:
        raise ValueError("No table data found")

    dataframe = pd.DataFrame(rows)

    if headers and len(headers) == len(dataframe.columns):
        dataframe.columns = headers

    return dataframe

