        raise ValueError("source_dir and target_dir must exist and be directories")

    normalized_extensions = {
        extension.lower() if extension.startswith(".") else f".{extension.lower()}"
        for extension in extensions
    }

    moved_count = 0

    for file_path in source.iterdir():
        if file_path.is_file() and file_path.suffix.lower() in normalized_extensions:
            shutil.move(str(file_path), str(target / file_path.name))
            moved_count += 1

    return moved_count

import pandas as pd
import folium
from geopy.geocoders import Photon


def task_func(dic):
    geolocator = Photon(user_agent="geoapiExercises")

    def records_from_input(data):
        if data is None:
            return []

        if isinstance(data, pd.DataFrame):
            return data.to_dict("records")

        if isinstance(data, dict):
            normalized_keys = {
                str(key).strip().lower().replace("_", " ")
                for key in data
            }
            field_names = {
                "address", "location", "place", "query",
                "latitude", "lat", "longitude", "lon", "lng",
                "name", "title", "label", "coordinates"
            }

            if normalized_keys & field_names:
                if any(
                    isinstance(value, (list, tuple, pd.Series, pd.Index))
                    for value in data.values()
                ):
                    try:
                        return pd.DataFrame(data).to_dict("records")
                    except Exception:
                        return [data]
                return [data]

            return [
                value if isinstance(value, dict)
                else {"name": key, "address": value}
                for key, value in data.items()
            ]

        if isinstance(data, (list, tuple)):
            if len(data) == 2 and all(
                not isinstance(value, (dict, list, tuple))
                for value in data
            ):
                return [data]
            return list(data)

        return [data]

    def get_value(record, names):
        if not isinstance(record, dict):
            return None

        normalized = {
            str(key).strip().lower().replace("_", " "): value
            for key, value in record.items()
        }

        for name in names:
            if name in normalized:
                return normalized[name]
        return None

    def numeric_value(value):
        if value is None or isinstance(value, bool):
            return None
        try:
            number = float(value)
        except (TypeError, ValueError):
            return None
        return number if number == number else None

    def valid_coordinates(latitude, longitude):
        return (
            latitude is not None
            and longitude is not None
            and -90 <= latitude <= 90
            and -180 <= longitude <= 180
        )

    locations = []

    for record in records_from_input(dic):
        address = None
        label = None
        latitude = None
        longitude = None

        if isinstance(record, str):
            address = record.strip()
            label = address
        elif isinstance(record, dict):
            address = get_value(record, {
                "address", "location", "place", "query", "full address"
            })
            if isinstance(address, str):
                address = address.strip()

            label = get_value(record, {"name", "title", "label"})
            if not label:
                label = address

            latitude = numeric_value(
                get_value(record, {"latitude", "lat"})
            )
            longitude = numeric_value(
                get_value(record, {"longitude", "lon", "lng"})
            )

            coordinates = get_value(record, {"coordinates"})
            if (
                (latitude is None or longitude is None)
                and isinstance(coordinates, (list, tuple))
                and len(coordinates) >= 2
            ):
                latitude = numeric_value(coordinates[0])
                longitude = numeric_value(coordinates[1])
        elif isinstance(record, (list, tuple)) and len(record) >= 2:
            latitude = numeric_value(record[0])
            longitude = numeric_value(record[1])
            label = str(record)
        else:
            continue

        if not valid_coordinates(latitude, longitude):
            if isinstance(address, str) and address:
                try:
                    result = geolocator.geocode(address)
                    if result is not None:
                        latitude = numeric_value(
                            getattr(result, "latitude", None)
                        )
                        longitude = numeric_value(
                            getattr(result, "longitude", None)
                        )
                except Exception:
                    latitude = longitude = None

        if valid_coordinates(latitude, longitude):
            locations.append((latitude, longitude, label))

    center = (
        [locations[0][0], locations[0][1]]
        if locations
        else [0, 0]
    )

    result_map = folium.Map(location=center, zoom_start=2)

    for latitude, longitude, label in locations:
        folium.Marker(
            location=[latitude, longitude],
            popup=str(label) if label else None,
        ).add_to(result_map)

    return result_map

