import numpy as np
import random
from datetime import datetime, timedelta


def task_func(
    rows=3,
    columns=2,
    start_date=datetime(2021, 1, 1),
    end_date=datetime(2021, 12, 31),
    seed=0,
):
    if isinstance(rows, bool) or not isinstance(rows, (int, np.integer)):
        raise TypeError("rows must be an integer")
    if isinstance(columns, bool) or not isinstance(columns, (int, np.integer)):
        raise TypeError("columns must be an integer")
    if rows < 0 or columns < 0:
        raise ValueError("rows and columns must be non-negative")

    if not isinstance(start_date, datetime):
        raise TypeError("start_date must be a datetime instance")
    if not isinstance(end_date, datetime):
        raise TypeError("end_date must be a datetime instance")
    if start_date > end_date:
        raise ValueError("start_date must not be later than end_date")

    size = rows * columns

    if size == 0:
        return np.empty((rows, columns), dtype=object)

    available_days = (end_date - start_date).days + 1
    if size > available_days:
        raise ValueError("The date range does not contain enough unique dates")

    rng = random.Random(seed)
    offsets = rng.sample(range(available_days), size)

    dates = [start_date + timedelta(days=offset) for offset in offsets]
    return np.array(dates, dtype=object).reshape(rows, columns)

import numpy as np
import matplotlib.pyplot as plt
from scipy.stats import norm


def task_func(n_samples=1000, mu=0, sigma=1, random_seed=0):
    if isinstance(n_samples, (bool, np.bool_)) or not isinstance(
        n_samples, (int, np.integer)
    ):
        raise TypeError("n_samples must be a non-negative integer")
    if n_samples < 0:
        raise ValueError("n_samples must be non-negative")

    if not isinstance(mu, (int, float, np.integer, np.floating)) or not np.isfinite(mu):
        raise ValueError("mu must be a finite real number")
    if not isinstance(sigma, (int, float, np.integer, np.floating)) or not np.isfinite(
        sigma
    ):
        raise ValueError("sigma must be a finite real number")
    if sigma <= 0:
        raise ValueError("sigma must be greater than zero")

    try:
        rng = np.random.default_rng(random_seed)
    except (TypeError, ValueError) as exc:
        raise ValueError("random_seed must be a valid NumPy random seed") from exc

    samples = rng.normal(loc=mu, scale=sigma, size=n_samples)

    _, ax = plt.subplots()
    ax.hist(samples, density=True)

    if n_samples == 0:
        x_min, x_max = mu - 4 * sigma, mu + 4 * sigma
    else:
        x_min = float(np.min(samples))
        x_max = float(np.max(samples))
        if x_min == x_max:
            padding = max(float(sigma), 1e-12)
            x_min -= padding
            x_max += padding

    x = np.linspace(x_min, x_max, 1000)
    ax.plot(
        x,
        norm.pdf(x, loc=mu, scale=sigma),
        color="red",
        linewidth=2,
    )

    return ax, samples

