import requests
from pathlib import Path
import zipfile

# Constants
DOWNLOAD_DIR = Path("downloads")
ZIP_DIR = Path("unzipped_files")


def task_func(url, filename):
    try:
        DOWNLOAD_DIR.mkdir(parents=True, exist_ok=True)
        download_root = DOWNLOAD_DIR.resolve()
        archive_path = (DOWNLOAD_DIR / filename).resolve()

        if archive_path != download_root and download_root not in archive_path.parents:
            raise OSError("Unsafe download path detected")

        archive_path.parent.mkdir(parents=True, exist_ok=True)
    except (OSError, RuntimeError, TypeError, ValueError) as exc:
        return (f"Error handling download path: {exc}", [])

    try:
        response = requests.get(url, timeout=30)
        response.raise_for_status()
        archive_path.write_bytes(response.content)
    except requests.RequestException as exc:
        return (f"Error downloading file: {exc}", [])
    except (OSError, ValueError) as exc:
        return (f"Error saving downloaded file: {exc}", [])

    try:
        ZIP_DIR.mkdir(parents=True, exist_ok=True)
        destination = ZIP_DIR.resolve()
        filenames = []

        with zipfile.ZipFile(archive_path, "r") as archive:
            for member in archive.infolist():
                member_path = (destination / member.filename).resolve()

                if member_path != destination and destination not in member_path.parents:
                    raise OSError("Unsafe ZIP path detected")

                if member.is_dir():
                    member_path.mkdir(parents=True, exist_ok=True)
                    continue

                member_path.parent.mkdir(parents=True, exist_ok=True)
                with archive.open(member) as source, member_path.open("wb") as target:
                    target.write(source.read())

                filenames.append(member.filename)

        return ("File downloaded and extracted successfully", filenames)

    except Exception as exc:
        return (f"Error extracting file: {exc}", [])

