import pandas as pd
from datetime import datetime
import matplotlib.pyplot as plt

# Constants
ROOMS = ["Room1", "Room2", "Room3", "Room4", "Room5"]


def task_func(date_str, booking_data):
    if (
        not isinstance(date_str, str)
        or len(date_str) != 10
        or date_str[4] != "-"
        or date_str[7] != "-"
        or not date_str[:4].isdigit()
        or not date_str[5:7].isdigit()
        or not date_str[8:].isdigit()
    ):
        raise ValueError("date_str must follow the YYYY-MM-DD format")

    try:
        requested_date = datetime.strptime(date_str, "%Y-%m-%d").date()
    except ValueError as exc:
        raise ValueError("date_str must be a valid date") from exc

    if requested_date < datetime.now().date():
        raise ValueError("date_str cannot refer to a past date")

    booked_rooms = set()

    def normalize_date(value):
        if isinstance(value, datetime):
            return value.date()
        if hasattr(value, "date") and not isinstance(value, str):
            try:
                return value.date()
            except (TypeError, ValueError):
                pass
        if isinstance(value, str):
            try:
                return datetime.strptime(value, "%Y-%m-%d").date()
            except ValueError:
                return None
        return None

    def add_booking(room, date_value):
        if room in ROOMS and normalize_date(date_value) == requested_date:
            booked_rooms.add(room)

    if isinstance(booking_data, pd.DataFrame):
        records = booking_data.to_dict("records")
    elif isinstance(booking_data, dict):
        records = []
        for key, value in booking_data.items():
            values = value if isinstance(value, (list, tuple, set)) else [value]
            if key in ROOMS:
                for date_value in values:
                    add_booking(key, date_value)
            else:
                for room in values:
                    add_booking(room, key)
    elif booking_data is None:
        records = []
    else:
        records = booking_data

    for record in records:
        if isinstance(record, dict):
            room = record.get("Room", record.get("room"))
            date_value = record.get(
                "Date",
                record.get(
                    "date",
                    record.get("booking_date", record.get("bookingDate")),
                ),
            )
            if room is not None and date_value is not None:
                add_booking(room, date_value)
        elif isinstance(record, (list, tuple)) and len(record) >= 2:
            add_booking(record[0], record[1])

    status_df = pd.DataFrame(
        {
            "Room": ROOMS,
            "Status": [
                "Booked" if room in booked_rooms else "Available"
                for room in ROOMS
            ],
        }
    )

    counts = (
        status_df["Status"]
        .value_counts()
        .reindex(["Booked", "Available"], fill_value=0)
    )

    _, ax = plt.subplots()
    counts.plot(
        kind="bar",
        ax=ax,
        color=["#d95f02", "#1b9e77"],
    )
    ax.set_xlabel("Booking Status")
    ax.set_ylabel("Number of Rooms")
    ax.set_title(f"Room Booking Status for {date_str}")
    ax.tick_params(axis="x", rotation=0)

    return status_df, ax

import json
import pandas as pd
import numpy as np
from collections import defaultdict


def task_func(input_file="data.json"):
    with open(input_file, "r", encoding="utf-8") as file:
        data = json.load(file)

    if not isinstance(data, list):
        raise ValueError("The JSON root must be a list of dictionaries.")

    values_by_key = defaultdict(list)

    for item in data:
        if not isinstance(item, dict):
            raise ValueError("Each item in the JSON list must be a dictionary.")

        for key, value in item.items():
            if isinstance(value, (int, float)) and not isinstance(value, bool):
                try:
                    if np.isfinite(value):
                        values_by_key[key].append(value)
                except (TypeError, ValueError, OverflowError):
                    continue

    statistics = {
        key: {
            "mean": np.mean(values),
            "median": np.median(values),
        }
        for key, values in values_by_key.items()
    }

    df = pd.DataFrame.from_dict(statistics, orient="index")
    df = df.reindex(columns=["mean", "median"])
    df.index.name = "variable"

    return df.sort_index()

