import subprocess
import os
import glob

# Constants
ARCHIVE_DIR = '/tmp/archive'


def task_func(pattern):
    if not isinstance(pattern, str) or not pattern:
        raise ValueError("pattern must be a non-empty string")

    matches = []
    seen = set()

    for path in glob.glob(pattern):
        absolute_path = os.path.abspath(path)
        if absolute_path not in seen and os.path.isfile(absolute_path):
            seen.add(absolute_path)
            matches.append(absolute_path)

    if not matches:
        raise FileNotFoundError(f"No files matched pattern: {pattern!r}")

    os.makedirs(ARCHIVE_DIR, exist_ok=True)

    counter = 0
    while True:
        archive_file = os.path.join(
            ARCHIVE_DIR,
            f"archive_{os.getpid()}_{counter}.tar.gz",
        )
        try:
            fd = os.open(
                archive_file,
                os.O_CREAT | os.O_EXCL | os.O_WRONLY,
                0o600,
            )
            os.close(fd)
            break
        except FileExistsError:
            counter += 1

    common_parent = os.path.commonpath(
        [os.path.dirname(path) for path in matches]
    )
    relative_paths = [
        os.path.relpath(path, common_parent)
        for path in matches
    ]

    try:
        subprocess.run(
            [
                "tar",
                "-czf",
                archive_file,
                "-C",
                common_parent,
                "--",
                *relative_paths,
            ],
            check=True,
        )
    except Exception:
        try:
            os.remove(archive_file)
        except OSError:
            pass
        raise

    for path in matches:
        try:
            os.remove(path)
        except OSError as exc:
            raise RuntimeError(
                f"Failed to delete original file after archiving: {path}"
            ) from exc

    return archive_file

