import string

# Constants
LETTERS = string.ascii_letters
DIGITS = string.digits


def task_func(length, num_digits):
    """Generate a random password with the specified length and digit count."""
    if isinstance(length, bool) or not isinstance(length, int):
        raise TypeError("length must be an integer")
    if isinstance(num_digits, bool) or not isinstance(num_digits, int):
        raise TypeError("num_digits must be an integer")
    if length < 0:
        raise ValueError("length must be non-negative")
    if not 0 <= num_digits <= length:
        raise ValueError("num_digits must be between 0 and length")

    password = [
        random.choice(LETTERS) for _ in range(length - num_digits)
    ]
    password.extend(random.choice(DIGITS) for _ in range(num_digits))
    random.shuffle(password)

    return "".join(password)

import numpy as np
import itertools
import json


def task_func(data_list, json_file_name="mean_values.json"):
    if data_list is None or isinstance(data_list, (str, bytes)):
        raise TypeError("data_list must be an iterable of sequences")

    try:
        rows = list(data_list)
    except TypeError as exc:
        raise TypeError("data_list must be an iterable of sequences") from exc

    for row in rows:
        if isinstance(row, (str, bytes)) or not hasattr(row, "__iter__"):
            raise TypeError("Each item in data_list must be a sequence")

    sentinel = object()
    columns = itertools.zip_longest(*rows, fillvalue=sentinel) if rows else []
    result = {}

    for position, column in enumerate(columns, start=1):
        values = [value for value in column if value is not sentinel]
        if not values:
            continue

        try:
            numeric_values = np.asarray(values, dtype=float)
        except (TypeError, ValueError) as exc:
            raise ValueError(
                f"Values at position {position} must be numeric"
            ) from exc

        if np.all(np.isnan(numeric_values)):
            continue

        result[f"Position {position}"] = float(np.nanmean(numeric_values))

    if json_file_name is not None:
        with open(json_file_name, "w", encoding="utf-8") as json_file:
            json.dump(result, json_file, indent=4)

    return result

