import matplotlib.pyplot as plt
import pandas as pd


def task_func(df, tuples, n_plots):
    if not isinstance(df, pd.DataFrame):
        raise TypeError("df must be a pandas DataFrame")
    if isinstance(n_plots, bool) or not isinstance(n_plots, int):
        raise TypeError("n_plots must be an integer")
    if n_plots < 0:
        raise ValueError("n_plots must be non-negative")

    try:
        tuples = list(tuples)
    except TypeError as exc:
        raise TypeError("tuples must be iterable") from exc

    column_count = len(df.columns)
    for values in tuples:
        if not isinstance(values, tuple):
            raise TypeError("each item in tuples must be a tuple")
        if len(values) != column_count:
            raise ValueError(
                "each tuple must contain exactly one value per DataFrame column"
            )

    def is_missing(value):
        result = pd.isna(value)
        try:
            return result.ndim == 0 and bool(result)
        except (AttributeError, TypeError, ValueError):
            return False

    def values_equal(left, right):
        if is_missing(left) and is_missing(right):
            return True
        if is_missing(left) or is_missing(right):
            return False

        try:
            result = left == right
            return bool(result)
        except (TypeError, ValueError):
            return False

    def row_matches(row):
        return any(
            all(
                values_equal(row.iloc[index], value)
                for index, value in enumerate(row_values)
            )
            for row_values in tuples
        )

    if tuples:
        matches = df.apply(row_matches, axis=1)
        remaining_df = df.loc[~matches].copy()
    else:
        remaining_df = df.copy()

    column_pairs = list(combinations(remaining_df.columns, 2))
    selected_pairs = sample(column_pairs, min(n_plots, len(column_pairs)))

    plots = []
    for column_x, column_y in selected_pairs:
        _, axes = plt.subplots()
        axes.scatter(remaining_df[column_x], remaining_df[column_y])
        axes.set_xlabel(str(column_x))
        axes.set_ylabel(str(column_y))
        plots.append(((column_x, column_y), axes))

    return remaining_df, plots

