import os
from pathlib import Path
import glob
import shutil


def task_func(source_directory: str, target_directory: str):
    source = Path(source_directory)
    target = Path(target_directory)

    if not source.exists():
        raise FileNotFoundError(source)
    if not source.is_dir():
        raise NotADirectoryError(source)

    target_resolved = target.resolve()
    extensions = {".txt", ".docx", ".xlsx", ".csv"}

    files = []
    for path in source.rglob("*"):
        if not path.is_file():
            continue

        resolved_path = path.resolve()
        if target_resolved == resolved_path or target_resolved in resolved_path.parents:
            continue

        if path.suffix in extensions:
            files.append(path)

    files.sort(key=lambda path: str(path))
    target.mkdir(parents=True, exist_ok=True)

    moved_count = 0

    for source_file in files:
        destination = target / source_file.name

        if os.path.lexists(destination):
            counter = 1
            while True:
                destination = target / (
                    f"{source_file.stem}-{counter}{source_file.suffix}"
                )
                if not os.path.lexists(destination):
                    break
                counter += 1

        shutil.move(str(source_file), str(destination))
        moved_count += 1

    return moved_count

