import re
import math

def task_func(s):
    number_pattern = re.compile(
        r"[+-]?(?:(?:\d+(?:\.\d*)?)|(?:\.\d+))(?:[eE][+-]?\d+)?"
    )

    count = 0
    sqrt_sum = 0.0

    for token in s.split(","):
        token = token.strip()

        if not number_pattern.fullmatch(token):
            continue

        value = float(token)
        if value < 0:
            continue

        count += 1
        sqrt_sum += math.sqrt(value)

    return {"count": count, "sqrt_sum": sqrt_sum}

