import pandas as pd
from sklearn.preprocessing import LabelEncoder


def task_func(df, dct, columns=None):
    if not isinstance(df, pd.DataFrame):
        raise ValueError("df must be a pandas DataFrame")

    result = df.copy().replace(dct)

    categorical_columns = (
        list(columns)
        if columns is not None
        else result.select_dtypes(include=["object", "category"]).columns.tolist()
    )

    for column in categorical_columns:
        values = result[column]
        mask = values.notna()

        if not mask.any():
            continue

        encoder = LabelEncoder()
        encoded = encoder.fit_transform(values.loc[mask])

        if mask.all():
            result[column] = encoded
        else:
            encoded_values = pd.Series(float("nan"), index=values.index)
            encoded_values.loc[mask] = encoded
            result[column] = encoded_values

    for column in result.select_dtypes(include="number").columns:
        mean = result[column].mean()
        std = result[column].std()
        result[column] = (result[column] - mean) / std

    return result

