        "a", "an", "and", "are", "as", "at", "be", "but", "by", "for",
        "from", "has", "have", "he", "her", "his", "i", "if", "in",
        "is", "it", "its", "me", "my", "of", "on", "or", "our", "she",
        "that", "the", "their", "them", "there", "they", "this", "to",
        "was", "we", "were", "what", "when", "where", "which", "who",
        "will", "with", "you", "your",
    }

    try:
        nltk_stopwords = set(stopwords.words("english"))
    except LookupError:
        nltk_stopwords = set()

    stopword_set = manual_stopwords | {
        word.lower() for word in nltk_stopwords
    }

    words = re.findall(r"\b[\w']+\b", text.lower())

    return {
        word: 1
        for word in words
        if word not in stopword_set
    }

import numpy as np
from sklearn.cluster import KMeans


def task_func(data, n_clusters=2, random_state=0):
    if len(data) == 0:
        raise ValueError("data must not be empty")

    if isinstance(n_clusters, (bool, np.bool_)) or not isinstance(
        n_clusters, (int, np.integer)
    ) or n_clusters <= 0:
        raise ValueError("n_clusters must be a positive integer")

    if n_clusters > len(data):
        raise ValueError("n_clusters cannot exceed the number of data points")

    coordinates = []
    for item in data:
        if len(item) != 3:
            raise ValueError(
                "each item must contain an identifier and two coordinates"
            )

        x, y = item[1], item[2]
        if (
            isinstance(x, (bool, np.bool_))
            or isinstance(y, (bool, np.bool_))
            or not isinstance(x, (int, float, np.integer, np.floating))
            or not isinstance(y, (int, float, np.integer, np.floating))
        ):
            raise ValueError("coordinates must be numeric")

        coordinates.append((float(x), float(y)))

    points = np.asarray(coordinates, dtype=float)
    if not np.isfinite(points).all():
        raise ValueError("coordinates must be finite")

    model = KMeans(
        n_clusters=int(n_clusters),
        random_state=random_state,
        n_init=10,
    )
    model.fit(points)

    return model.labels_

import pandas as pd
from scipy.stats import pearsonr


def task_func(data):
    if len(data) < 2:
        return float("nan")

    score_candidates = (
        "score",
        "scores",
        "numerical_score",
        "numerical_scores",
    )
    grade_candidates = (
        "grade",
        "grades",
        "categorical_grade",
        "categorical_grades",
    )

    score_column = next(
        (column for column in score_candidates if column in data.columns),
        data.columns[0],
    )
    grade_column = next(
        (column for column in grade_candidates if column in data.columns),
        next(column for column in data.columns if column != score_column),
    )

    scores = pd.to_numeric(data[score_column], errors="coerce")
    grades = data[grade_column]

    if isinstance(grades.dtype, pd.CategoricalDtype):
        grade_codes = grades.cat.codes.astype(float)
        grade_codes[grade_codes < 0] = float("nan")
    else:
        normalized = grades.astype("string").str.strip()
        valid_grades = normalized.dropna()

        letter_order = [
            "F", "E", "D-", "D", "D+", "C-", "C", "C+",
            "B-", "B", "B+", "A-", "A", "A+",
        ]
        unique_grades = list(valid_grades.unique())
        upper_grades = {value.upper() for value in unique_grades}

        if upper_grades and upper_grades.issubset(set(letter_order)):
            ordered_grades = [
                grade for grade in letter_order if grade in upper_grades
            ]
            mapping = {grade: rank for rank, grade in enumerate(ordered_grades)}
            grade_codes = normalized.str.upper().map(mapping).astype(float)
        else:
            numeric_grades = pd.to_numeric(valid_grades, errors="coerce")
            if numeric_grades.notna().all():
                ordered_grades = sorted(
                    unique_grades,
                    key=lambda value: float(value),
                )
            else:
                ordered_grades = sorted(unique_grades)

            mapping = {
                grade: rank for rank, grade in enumerate(ordered_grades)
            }
            grade_codes = normalized.map(mapping).astype(float)

    valid = scores.notna() & grade_codes.notna()

    if valid.sum() < 2:
        return float("nan")

    valid_scores = scores[valid]
    valid_grades = grade_codes[valid]

    if valid_scores.nunique() < 2 or valid_grades.nunique() < 2:
        return float("nan")

    correlation, _ = pearsonr(valid_scores, valid_grades)
    return float(correlation)

import numpy as np
