import collections
from queue import PriorityQueue
import random

# Constants
LETTERS = ['a', 'b', 'c', 'd', 'e']


def task_func(string_length=100):
    if isinstance(string_length, bool) or not isinstance(string_length, int):
        raise TypeError("string_length must be a non-negative integer")
    if string_length < 0:
        raise ValueError("string_length must be non-negative")

    generated_string = ''.join(
        random.choice(LETTERS) for _ in range(string_length)
    )
    frequencies = collections.Counter(generated_string)

    queue = PriorityQueue()
    letter_order = {letter: index for index, letter in enumerate(LETTERS)}

    for letter, frequency in frequencies.items():
        queue.put((-frequency, letter_order[letter], letter))

    result = collections.OrderedDict()
    while not queue.empty():
        _, _, letter = queue.get()
        result[letter] = frequencies[letter]

    return result

