import os
import re
import shutil


def task_func(source_directory: str, target_directory: str, pattern: str = r"\d{4}") -> int:
    if not os.path.isdir(source_directory):
        return 0

    regex = re.compile(pattern)
    os.makedirs(target_directory, exist_ok=True)

    if os.path.realpath(source_directory) == os.path.realpath(target_directory):
        return 0

    moved_count = 0

    with os.scandir(source_directory) as entries:
        for entry in entries:
            try:
                if not entry.is_file() or not regex.search(entry.name):
                    continue

                shutil.move(entry.path, os.path.join(target_directory, entry.name))
                moved_count += 1
            except (OSError, shutil.Error):
                continue

    return moved_count

