import requests
import logging


def task_func(repo_url: str) -> dict:
    """Fetch and return information about a GitHub repository."""
    logger = logging.getLogger(__name__)

    try:
        response = requests.get(repo_url, timeout=10)

        headers = getattr(response, "headers", {})
        remaining = headers.get("X-RateLimit-Remaining")
        if (
            getattr(response, "status_code", None) == 403
            and str(remaining) == "0"
        ):
            logger.error("GitHub API rate limit exceeded.")

        response.raise_for_status()

        try:
            repository_info = response.json()
        except (ValueError, TypeError) as exc:
            raise requests.exceptions.RequestException(
                "The API returned invalid JSON."
            ) from exc

        if not isinstance(repository_info, dict):
            raise requests.exceptions.RequestException(
                "The API response is not a dictionary."
            )

        open_issues_count = repository_info.get("open_issues_count")
        if (
            isinstance(open_issues_count, (int, float))
            and not isinstance(open_issues_count, bool)
            and open_issues_count > 1000
        ):
            logger.warning(
                "Repository has more than 1000 open issues: %s",
                open_issues_count,
            )

        return repository_info

    except requests.exceptions.HTTPError:
        logger.error(
            "HTTP error while fetching repository information.",
            exc_info=True,
        )
        raise
    except requests.exceptions.RequestException:
        logger.error(
            "Request error while fetching repository information.",
            exc_info=True,
        )
        raise

import matplotlib.pyplot as plt
from scipy.optimize import curve_fit


def task_func(X, Y):
    import numpy as np

    def quadratic(x, a, b, c):
        return a * x**2 + b * x + c

    try:
        x_values = np.asarray(X, dtype=float)
        y_values = np.asarray(Y, dtype=float)
    except (TypeError, ValueError) as exc:
        raise ValueError("X and Y must contain numeric values.") from exc

    if x_values.ndim != 1 or y_values.ndim != 1:
        raise ValueError("X and Y must be one-dimensional.")

    if len(x_values) != len(y_values):
        raise ValueError("X and Y must have the same length.")

    if len(x_values) < 3:
        raise ValueError("At least three data points are required.")

    if not np.all(np.isfinite(x_values)) or not np.all(np.isfinite(y_values)):
        raise ValueError("X and Y must contain only finite values.")

    if len(np.unique(x_values)) < 3:
        raise ValueError("At least three distinct X values are required.")

    parameters, _ = curve_fit(quadratic, x_values, y_values)

    _, axes = plt.subplots()
    axes.scatter(x_values, y_values, label="Data")

    x_fit = np.linspace(x_values.min(), x_values.max(), 200)
    axes.plot(x_fit, quadratic(x_fit, *parameters), label="Quadratic fit")

    axes.set_xlabel("X")
    axes.set_ylabel("Y")
    axes.legend()

    return [float(parameter) for parameter in parameters], axes

