import re
import os
import glob
from pathlib import Path


def task_func(pattern, directory, extensions):
    if not os.path.isdir(directory):
        raise NotADirectoryError(directory)

    regex = re.compile(pattern, re.IGNORECASE)

    if extensions is None:
        allowed_extensions = None
    elif isinstance(extensions, (str, os.PathLike)):
        allowed_extensions = {str(extensions).lower()}
    else:
        allowed_extensions = {str(extension).lower() for extension in extensions}

    if allowed_extensions:
        allowed_extensions = {
            extension if extension.startswith(".") else f".{extension}"
            for extension in allowed_extensions
        }

    results = []

    for root, directories, filenames in os.walk(directory, followlinks=False):
        directories[:] = [
            name
            for name in directories
            if not os.path.islink(os.path.join(root, name))
        ]

        for filename in filenames:
            path = os.path.join(root, filename)

            if os.path.islink(path) or not os.path.isfile(path):
                continue

            if (
                allowed_extensions
                and Path(filename).suffix.lower() not in allowed_extensions
            ):
                continue

            try:
                with open(path, "r", encoding="utf-8", errors="ignore") as file:
                    if regex.search(file.read()):
                        results.append(os.path.abspath(os.path.normpath(path)))
            except OSError:
                continue

    return {"list": sorted(results)}

