# Constants
COLUMNS = ['A', 'B', 'C', 'D', 'E']


def task_func(df: pd.DataFrame, tuples: list, n_plots: int) -> (pd.DataFrame, list):
    if not isinstance(df, pd.DataFrame):
        raise ValueError("df must be a pandas DataFrame")

    if not isinstance(n_plots, int) or isinstance(n_plots, bool) or n_plots < 0:
        raise ValueError("n_plots must be a non-negative integer")

    missing_columns = [column for column in COLUMNS if column not in df.columns]
    if missing_columns:
        raise ValueError(f"Missing required columns: {missing_columns}")

    filtered_df = df.copy()

    for values in tuples:
        try:
            if len(values) != len(COLUMNS):
                raise ValueError
        except (TypeError, ValueError):
            raise ValueError("Each filter tuple must contain exactly five values")

        mask = pd.Series(True, index=filtered_df.index)

        for column, value in zip(COLUMNS, values):
            matches = filtered_df[column].eq(value).fillna(False)

            try:
                value_is_missing = bool(pd.isna(value))
            except (TypeError, ValueError):
                value_is_missing = False

            if value_is_missing:
                matches = matches | filtered_df[column].isna()

            mask &= matches

        filtered_df = filtered_df.loc[~mask]

    if filtered_df.empty:
        return filtered_df, []

    plots = [
        sns.jointplot(
            data=filtered_df,
            x=x_column,
            y=y_column,
        )
        for _ in range(n_plots)
        for x_column, y_column in [sample(COLUMNS, 2)]
    ]

    return filtered_df, plots

