import sqlite3
import pandas as pd
import csv
from io import StringIO

# Constants
DATABASE_NAME = 'test.db'
TABLE_NAME = 'test_table'


def _quote_identifier(identifier):
    return '"' + identifier.replace('"', '""') + '"'


def task_func(csv_input):
    opened_file = None

    try:
        if isinstance(csv_input, (str, bytes)) or hasattr(csv_input, "__fspath__"):
            opened_file = open(
                csv_input,
                "r",
                newline="",
                encoding="utf-8",
            )
            stream = opened_file
        elif hasattr(csv_input, "read"):
            stream = csv_input
        else:
            raise TypeError(
                "csv_input must be a file path or a file-like object"
            )

        rows = list(csv.reader(stream, strict=True))

        with sqlite3.connect(DATABASE_NAME) as connection:
            table_name = _quote_identifier(TABLE_NAME)
            connection.execute(f"DROP TABLE IF EXISTS {table_name}")

            if not rows:
                return pd.DataFrame()

            headers = rows[0]

            if not headers or any(not header for header in headers):
                raise ValueError("CSV headers must be non-empty")

            if len({header.casefold() for header in headers}) != len(headers):
                raise ValueError("CSV headers must be unique")

            if any("\x00" in header for header in headers):
                raise ValueError("CSV headers cannot contain null characters")

            columns = ", ".join(
                f"{_quote_identifier(header)} TEXT" for header in headers
            )
            connection.execute(f"CREATE TABLE {table_name} ({columns})")

            placeholders = ", ".join("?" for _ in headers)
            insert_sql = (
                f"INSERT INTO {table_name} VALUES ({placeholders})"
            )

            values = []
            for row in rows[1:]:
                if len(row) > len(headers):
                    raise ValueError(
                        "CSV row contains more fields than the headers"
                    )
                values.append(row + [None] * (len(headers) - len(row)))

            if values:
                connection.executemany(insert_sql, values)

            return pd.read_sql_query(
                f"SELECT * FROM {table_name}",
                connection,
            )

    finally:
        if opened_file is not None:
            opened_file.close()

