        x_column, y_column = df.columns
        heights = pd.to_numeric(df[y_column], errors="raise")

        _, ax = plt.subplots()
        ax.bar(df[x_column], heights)
        ax.set_xlabel(x_column)
        ax.set_ylabel(y_column)

        return df, ax
    except ValueError:
        raise
    except Exception as exc:
        raise ValueError("The produced CSV is invalid.") from exc

import pandas as pd
import numpy as np
from sklearn.preprocessing import MinMaxScaler

def task_func(df):
    required_columns = {"id", "Age", "Income"}
    missing_columns = required_columns - set(df.columns)

    if missing_columns:
        raise ValueError(
            f"Missing required columns: {sorted(missing_columns)}"
        )

    scaled_df = df.copy()

    for column in ("Age", "Income"):
        scaled_df[column] = scaled_df[column].astype(float)

    if scaled_df.empty:
        return (
            scaled_df,
            (np.array([], dtype=int), np.array([], dtype=float)),
        )

    grouped = scaled_df.groupby("id", dropna=False, sort=False)

    for positions in grouped.indices.values():
        for column in ("Age", "Income"):
            column_position = scaled_df.columns.get_loc(column)
            values = scaled_df.iloc[positions, column_position].to_numpy(
                dtype=float
            )
            valid_mask = ~np.isnan(values)

            if valid_mask.any():
                scaler = MinMaxScaler()
                scaler.fit(values[valid_mask].reshape(-1, 1))

                scaled_values = values.copy()
                scaled_values[valid_mask] = scaler.transform(
                    values[valid_mask].reshape(-1, 1)
                ).ravel()
            else:
                scaled_values = values

            scaled_df.iloc[positions, column_position] = scaled_values

    income_values = scaled_df["Income"].dropna().to_numpy()

    if income_values.size:
        histogram_data = np.histogram(income_values, bins=10)
    else:
        histogram_data = (
            np.array([], dtype=int),
            np.array([], dtype=float),
        )

    return scaled_df, histogram_data

import pandas as pd
from collections import Counter


def task_func(data):
    required_keys = {"Name", "Age", "Scores"}

    if not isinstance(data, dict) or not required_keys.issubset(data):
        raise ValueError("Dictionary must contain Name, Age, and Scores keys.")

    dataframe = pd.DataFrame(data)
    sorted_dataframe = dataframe.sort_values(
        by=["Name", "Age"],
        ascending=True,
    ).reset_index(drop=True)

    scores_by_name = {}
    for name, scores in zip(dataframe["Name"], dataframe["Scores"]):
        scores_by_name.setdefault(name, []).extend(scores)

    average_scores = pd.Series(
        {
            name: pd.Series(scores).mean()
            for name, scores in scores_by_name.items()
        },
        dtype=float,
    )
    average_scores.index.name = None

    most_common = Counter(dataframe["Age"].tolist()).most_common(1)
    most_common_age = int(most_common[0][0]) if most_common else None

    return sorted_dataframe, average_scores, most_common_age

