import pandas as pd

def task_func(data_list, seed=None):
    rng = random.Random(seed)
    rows = []

    for original_string in data_list:
        substrings = [
            substring.strip()
            for substring in re.split(r",", original_string)
        ]
        rng.shuffle(substrings)

        rows.append({
            "Original String": original_string,
            "Shuffled String": ", ".join(substrings),
        })

    return pd.DataFrame(
        rows,
        columns=["Original String", "Shuffled String"],
    )

import json
import os

# Constants
PREFIXES = ["is_", "has_", "can_", "should_"]


def task_func(directory):
    statistics = {prefix: 0 for prefix in PREFIXES}

    def count_keys(value):
        if isinstance(value, dict):
            for key, nested_value in value.items():
                for prefix in PREFIXES:
                    if key.startswith(prefix):
                        statistics[prefix] += 1
                count_keys(nested_value)
        elif isinstance(value, list):
            for item in value:
                count_keys(item)

    for filename in os.listdir(directory):
        filepath = os.path.join(directory, filename)

        if not filename.endswith(".json") or not os.path.isfile(filepath):
            continue

        try:
            with open(filepath, "r", encoding="utf-8") as file:
                data = json.load(file)
        except json.JSONDecodeError:
            continue

        count_keys(data)

    return statistics

from datetime import datetime
import pandas as pd
# For Python versions lower than 3.9, use 'pytz' instead of 'zoneinfo'
try:
    from zoneinfo import ZoneInfo
except ImportError:
    from pytz import timezone as ZoneInfo

TIME_FORMAT = "%d/%m/%y %H:%M:%S.%f"


def task_func(time_strings, target_tz):
    target_zone = ZoneInfo(target_tz)
    utc_zone = ZoneInfo("UTC")
    results = []

    for time_string in time_strings:
        parsed_time = datetime.strptime(time_string, TIME_FORMAT)
        utc_time = parsed_time.replace(tzinfo=utc_zone)
        converted_time = utc_time.astimezone(target_zone)

        results.append(
            {
                "Original Time": time_string,
                "Converted Time": converted_time.strftime(TIME_FORMAT),
            }
        )

    return pd.DataFrame(
        results,
        columns=["Original Time", "Converted Time"],
    )

