import json
from datetime import datetime
import numpy as np
from decimal import Decimal


class CustomJSONEncoder(json.JSONEncoder):
    def default(self, obj):
        if isinstance(obj, datetime):
            return obj.isoformat()
        if isinstance(obj, np.ndarray):
            return obj.tolist()
        if isinstance(obj, Decimal):
            return float(obj)
        if isinstance(obj, np.integer):
            return int(obj)
        if isinstance(obj, np.floating):
            return float(obj)
        if isinstance(obj, np.bool_):
            return bool(obj)
        return super().default(obj)


def task_func(my_obj):
    return json.dumps(my_obj, cls=CustomJSONEncoder)

from itertools import groupby
from operator import itemgetter

# Constants
KEY_FUNC = itemgetter(0)


def task_func(my_dict):
    grouped_items = sorted(
        ((key[0], value) for key, value in my_dict.items()),
        key=KEY_FUNC,
    )

    aggregated_dict = {
        group_key: sum(value for _, value in group)
        for group_key, group in groupby(grouped_items, key=KEY_FUNC)
    }

    return aggregated_dict

