import numpy as np
from sklearn.preprocessing import StandardScaler
from sklearn.metrics import mean_squared_error


def task_func(num_samples=1000, k=5, d=2, random_seed=None):
    if num_samples <= 0:
        raise ValueError("num_samples must be positive")

    rng = np.random.RandomState(random_seed)
    original_data = rng.randn(num_samples)
    transformed_data = k * original_data + d

    standardized_data = StandardScaler().fit_transform(
        transformed_data.reshape(-1, 1)
    ).ravel()

    return float(mean_squared_error(transformed_data, standardized_data))

import pandas as pd
import os


def task_func(
    original_file_location="test.xlsx",
    new_file_location="new_test.xlsx",
    sheet_name="Sheet1",
):
    if not os.path.exists(original_file_location):
        raise FileNotFoundError(original_file_location)

    with pd.ExcelFile(original_file_location) as excel_file:
        if sheet_name not in excel_file.sheet_names:
            raise ValueError(f"Sheet '{sheet_name}' does not exist in the workbook.")

        data = pd.read_excel(excel_file, sheet_name=sheet_name)

    data.to_excel(new_file_location, index=False)
    return pd.read_excel(new_file_location)

